  <String, dynamic>{'id': "A1-U03-L39", 'level': 'A1', 'title': "Start et finish", 'subtitle': "Sous-chapitre 3 • Leçon 39/50", 'explanation': "Le verbe ou thème principal est **start**. Son sens de base ici est **commencer**. Apprends-le dans la phrase et observe comment il fonctionne avec le sujet et le contexte. Certains verbes ont plusieurs sens ; la phrase aide à choisir la bonne traduction.", 'example': "The class starts at eight. / I finish my homework.", 'french': "The class starts at eight. / I finish my homework.", 'question': "Which verb means « terminer »?", 'options': <String>["start", "finish", "come"], 'answer': 1, 'correction': "Finish signifie finir ou terminer.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L40", 'level': 'A1', 'title': "Play avec jeux et sports", 'subtitle': "Sous-chapitre 3 • Leçon 40/50", 'explanation': "Le verbe ou thème principal est **play**. Son sens de base ici est **jouer**. Apprends-le dans la phrase et observe comment il fonctionne avec le sujet et le contexte. Certains verbes ont plusieurs sens ; la phrase aide à choisir la bonne traduction.", 'example': "I play football. / They play chess.", 'french': "I play football. / They play chess.", 'question': "Choose the usual phrase.", 'options': <String>["play football", "do football", "make football"], 'answer': 0, 'correction': "Play s’utilise avec football et de nombreux jeux.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L41", 'level': 'A1', 'title': "Run et walk", 'subtitle': "Sous-chapitre 3 • Leçon 41/50", 'explanation': "Le verbe ou thème principal est **run**. Son sens de base ici est **courir**. Apprends-le dans la phrase et observe comment il fonctionne avec le sujet et le contexte. Certains verbes ont plusieurs sens ; la phrase aide à choisir la bonne traduction.", 'example': "I run fast. / I walk to school.", 'french': "I run fast. / I walk to school.", 'question': "Which verb means « marcher »?", 'options': <String>["run", "walk", "sleep"], 'answer': 1, 'correction': "Walk signifie marcher.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L42", 'level': 'A1', 'title': "Sit et stand", 'subtitle': "Sous-chapitre 3 • Leçon 42/50", 'explanation': "Le verbe ou thème principal est **sit**. Son sens de base ici est **s’asseoir / être assis**. Apprends-le dans la phrase et observe comment il fonctionne avec le sujet et le contexte. Certains verbes ont plusieurs sens ; la phrase aide à choisir la bonne traduction.", 'example': "Sit down, please. / Stand here.", 'french': "Sit down, please. / Stand here.", 'question': "Which verb means « se tenir debout »?", 'options': <String>["sit", "stand", "sleep"], 'answer': 1, 'correction': "Stand signifie se tenir debout.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L43", 'level': 'A1', 'title': "Sleep et wake up", 'subtitle': "Sous-chapitre 3 • Leçon 43/50", 'explanation': "Le verbe ou thème principal est **sleep**. Son sens de base ici est **dormir**. Apprends-le dans la phrase et observe comment il fonctionne avec le sujet et le contexte. Certains verbes ont plusieurs sens ; la phrase aide à choisir la bonne traduction.", 'example': "I sleep at night. / I wake up at six.", 'french': "I sleep at night. / I wake up at six.", 'question': "Wake up means…", 'options': <String>["fall asleep", "wake from sleep", "go to bed"], 'answer': 1, 'correction': "Wake up signifie se réveiller ; get up signifie se lever.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L44", 'level': 'A1', 'title': "Get up et go to bed", 'subtitle': "Sous-chapitre 3 • Leçon 44/50", 'explanation': "Le verbe ou thème principal est **get up**. Son sens de base ici est **se lever du lit**. Apprends-le dans la phrase et observe comment il fonctionne avec le sujet et le contexte. Certains verbes ont plusieurs sens ; la phrase aide à choisir la bonne traduction.", 'example': "I get up at seven. / I go to bed at ten.", 'french': "I get up at seven. / I go to bed at ten.", 'question': "Which phrase means « aller se coucher »?", 'options': <String>["get up", "go to bed", "wake up"], 'answer': 1, 'correction': "Go to bed signifie aller au lit pour dormir.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L45", 'level': 'A1', 'title': "Buy et pay", 'subtitle': "Sous-chapitre 3 • Leçon 45/50", 'explanation': "Le verbe ou thème principal est **buy**. Son sens de base ici est **acheter**. Apprends-le dans la phrase et observe comment il fonctionne avec le sujet et le contexte. Certains verbes ont plusieurs sens ; la phrase aide à choisir la bonne traduction.", 'example': "I buy bread. / I paid yesterday.", 'french': "I buy bread. / I paid yesterday.", 'question': "Past simple of buy?", 'options': <String>["buyed", "bought", "buying"], 'answer': 1, 'correction': "Buy est irrégulier : buy–bought–bought.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L46", 'level': 'A1', 'title': "Help et use", 'subtitle': "Sous-chapitre 3 • Leçon 46/50", 'explanation': "Le verbe ou thème principal est **help**. Son sens de base ici est **aider**. Apprends-le dans la phrase et observe comment il fonctionne avec le sujet et le contexte. Certains verbes ont plusieurs sens ; la phrase aide à choisir la bonne traduction.", 'example': "Can you help me? / I use my phone.", 'french': "Can you help me? / I use my phone.", 'question': "Which verb means « utiliser »?", 'options': <String>["help", "use", "eat"], 'answer': 1, 'correction': "Use signifie utiliser.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L47", 'level': 'A1', 'title': "Call et text", 'subtitle': "Sous-chapitre 3 • Leçon 47/50", 'explanation': "Le verbe ou thème principal est **call**. Son sens de base ici est **appeler**. Apprends-le dans la phrase et observe comment il fonctionne avec le sujet et le contexte. Certains verbes ont plusieurs sens ; la phrase aide à choisir la bonne traduction.", 'example': "I’ll call you. / Text me later.", 'french': "I’ll call you. / Text me later.", 'question': "Which verb fits sending an SMS?", 'options': <String>["text", "call", "sleep"], 'answer': 0, 'correction': "Text peut signifier envoyer un message écrit.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L48", 'level': 'A1', 'title': "Think et feel", 'subtitle': "Sous-chapitre 3 • Leçon 48/50", 'explanation': "Le verbe ou thème principal est **think**. Son sens de base ici est **penser**. Apprends-le dans la phrase et observe comment il fonctionne avec le sujet et le contexte. Certains verbes ont plusieurs sens ; la phrase aide à choisir la bonne traduction.", 'example': "I think it’s good. / I feel happy.", 'french': "I think it’s good. / I feel happy.", 'question': "Which verb introduces an opinion?", 'options': <String>["think", "feel", "sleep"], 'answer': 0, 'correction': "Think introduit souvent une pensée ou une opinion.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L49", 'level': 'A1', 'title': "Try et practise", 'subtitle': "Sous-chapitre 3 • Leçon 49/50", 'explanation': "Le verbe ou thème principal est **try**. Son sens de base ici est **essayer**. Apprends-le dans la phrase et observe comment il fonctionne avec le sujet et le contexte. Certains verbes ont plusieurs sens ; la phrase aide à choisir la bonne traduction.", 'example': "Try again. / Practice English every day.", 'french': "Try again. / Practice English every day.", 'question': "“Try again” means…", 'options': <String>["try once only", "try one more time", "stop now"], 'answer': 1, 'correction': "Try again encourage à faire une nouvelle tentative.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L50", 'level': 'A1', 'title': "Révision : base verbale et phrase complète", 'subtitle': "Sous-chapitre 3 • Leçon 50/50", 'explanation': "Le verbe ou thème principal est **Réutilise les verbes dans des phrases complètes. Observe le sujet, le temps, la négation et les mots qui accompagnent chaque verbe.**. Son sens de base ici est **I eat rice. Yesterday, I drank water. I want to learn English. = Je mange du riz. Hier, j’ai bu de l’eau. Je veux apprendre l’anglais.**. Apprends-le dans la phrase et observe comment il fonctionne avec le sujet et le contexte. Certains verbes ont plusieurs sens ; la phrase aide à choisir la bonne traduction.", 'example': "Which sentence is correct?", 'french': "Which sentence is correct?", 'question': "She speak English.", 'options': <String>["She speak English.", "I want to learn English.", "He have a book."], 'answer': 1, 'correction': "Écris trois phrases avec des verbes différents.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L01", 'level': 'A1', 'title': "Mother et father", 'subtitle': "Sous-chapitre 4 • Leçon 1/50", 'explanation': "Mother = mère ; father = père. Ce sont des noms de membres de la famille.", 'example': "My mother is kind. = Ma mère est gentille.", 'french': "Ma mère est gentille.", 'question': "Que signifie father ?", 'options': <String>["Père", "Frère", "Oncle"], 'answer': 0, 'correction': "Father signifie père.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L02", 'level': 'A1', 'title': "Parents et children", 'subtitle': "Sous-chapitre 4 • Leçon 2/50", 'explanation': "Parents signifie parents ; children signifie enfants. Child est le singulier, children le pluriel irrégulier.", 'example': "The parents have two children. = Les parents ont deux enfants.", 'french': "Les parents ont deux enfants.", 'question': "Quel est le pluriel de child ?", 'options': <String>["childs", "children", "childes"], 'answer': 1, 'correction': "Children est le pluriel irrégulier de child.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L03", 'level': 'A1', 'title': "Sister et brother", 'subtitle': "Sous-chapitre 4 • Leçon 3/50", 'explanation': "Sister signifie sœur ; brother signifie frère. Ces mots permettent de présenter les membres de sa famille.", 'example': "I have one sister and one brother. = J’ai une sœur et un frère.", 'french': "J’ai une sœur et un frère.", 'question': "Brother signifie…", 'options': <String>["Sœur", "Frère", "Cousin"], 'answer': 1, 'correction': "Brother signifie frère.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L04", 'level': 'A1', 'title': "Grandmother et grandfather", 'subtitle': "Sous-chapitre 4 • Leçon 4/50", 'explanation': "Grandmother signifie grand-mère ; grandfather signifie grand-père. Grandma et grandpa sont des formes familières.", 'example': "My grandfather is funny. = Mon grand-père est drôle.", 'french': "Mon grand-père est drôle.", 'question': "Grandmother signifie…", 'options': <String>["Grand-mère", "Tante", "Mère"], 'answer': 0, 'correction': "Grandmother désigne la mère de ton père ou de ta mère.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L05", 'level': 'A1', 'title': "Aunt et uncle", 'subtitle': "Sous-chapitre 4 • Leçon 5/50", 'explanation': "Aunt signifie tante ; uncle signifie oncle. Le mot cousin peut désigner un cousin ou une cousine.", 'example': "My aunt lives in a city. = Ma tante habite dans une ville.", 'french': "Ma tante habite dans une ville.", 'question': "Quel mot signifie tante ?", 'options': <String>["aunt", "uncle", "cousin"], 'answer': 0, 'correction': "Aunt signifie tante.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L06", 'level': 'A1', 'title': "Cousin et relatives", 'subtitle': "Sous-chapitre 4 • Leçon 6/50", 'explanation': "Cousin signifie cousin ou cousine. Relatives signifie parents au sens de membres de la famille élargie.", 'example': "My cousins are friendly. = Mes cousins sont amicaux.", 'french': "Mes cousins sont amicaux.", 'question': "Relatives signifie ici…", 'options': <String>["Voisins", "Membres de la famille", "Professeurs"], 'answer': 1, 'correction': "Relatives désigne les membres de la famille.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L07", 'level': 'A1', 'title': "Présenter sa famille", 'subtitle': "Sous-chapitre 4 • Leçon 7/50", 'explanation': "Utilise This is my… pour présenter un membre de la famille. Utilise he/she pour continuer à parler de la personne.", 'example': "This is my sister. She is funny. = Voici ma sœur. Elle est drôle.", 'french': "Voici ma sœur. Elle est drôle.", 'question': "Complète : This is my ___.", 'options': <String>["sister", "are sister", "my is sister"], 'answer': 0, 'correction': "This is my + nom présente une personne.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L08", 'level': 'A1', 'title': "Parler d’un friend", 'subtitle': "Sous-chapitre 4 • Leçon 8/50", 'explanation': "Friend signifie ami ou amie. Pour parler de plusieurs amis, ajoute généralement -s : friends.", 'example': "He is my friend. = C’est mon ami.", 'french': "C’est mon ami.", 'question': "Friend signifie…", 'options': <String>["Ami", "Enfant", "Voisinage"], 'answer': 0, 'correction': "Friend désigne une personne avec laquelle on est ami.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L09", 'level': 'A1', 'title': "Parler d’un best friend", 'subtitle': "Sous-chapitre 4 • Leçon 9/50", 'explanation': "Best friend signifie meilleur ami ou meilleure amie. Best est la forme superlative de good dans cette expression.", 'example': "Mia is my best friend. = Mia est ma meilleure amie.", 'french': "Mia est ma meilleure amie.", 'question': "Best friend signifie…", 'options': <String>["Un collègue", "Un meilleur ami", "Un professeur"], 'answer': 1, 'correction': "Best friend désigne la personne que l’on considère comme son meilleur ami.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L10", 'level': 'A1', 'title': "Man, woman, boy et girl", 'subtitle': "Sous-chapitre 4 • Leçon 10/50", 'explanation': "Man signifie homme ; woman signifie femme ; boy signifie garçon ; girl signifie fille. Au pluriel : men, women, boys, girls.", 'example': "The girl is happy. = La fille est contente.", 'french': "La fille est contente.", 'question': "Quel mot signifie garçon ?", 'options': <String>["boy", "woman", "man"], 'answer': 0, 'correction': "Boy signifie garçon.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L11", 'level': 'A1', 'title': "Baby et adult", 'subtitle': "Sous-chapitre 4 • Leçon 11/50", 'explanation': "Baby signifie bébé ; adult signifie adulte. Ce sont des mots utiles pour parler de l’âge et des étapes de la vie.", 'example': "The baby is sleeping. = Le bébé dort.", 'french': "Le bébé dort.", 'question': "Adult signifie…", 'options': <String>["Bébé", "Adulte", "Adolescent uniquement"], 'answer': 1, 'correction': "Adult désigne une personne adulte.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L12", 'level': 'A1', 'title': "Person et people", 'subtitle': "Sous-chapitre 4 • Leçon 12/50", 'explanation': "Person signifie personne au singulier ; people est le pluriel courant. Persons existe dans des contextes officiels, mais people est le plus naturel au quotidien.", 'example': "One person, two people. = Une personne, deux personnes.", 'french': "Une personne, deux personnes.", 'question': "Quel est le pluriel courant de person ?", 'options': <String>["persons toujours", "people", "persones"], 'answer': 1, 'correction': "People est le pluriel courant de person.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L13", 'level': 'A1', 'title': "Question Who is he?", 'subtitle': "Sous-chapitre 4 • Leçon 13/50", 'explanation': "Who signifie qui. Who is he? demande l’identité d’un homme ou d’un garçon dans le contexte.", 'example': "Who is he? He is my brother. = Qui est-il ? C’est mon frère.", 'french': "Qui est-il ? C’est mon frère.", 'question': "Quelle question signifie « Qui est-il ? »", 'options': <String>["Who is he?", "What is he?", "Where is he?"], 'answer': 0, 'correction': "Who demande l’identité d’une personne.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L14", 'level': 'A1', 'title': "Question Who is she?", 'subtitle': "Sous-chapitre 4 • Leçon 14/50", 'explanation': "Who is she? demande l’identité d’une femme ou d’une fille dans le contexte. La réponse peut commencer par She is…", 'example': "Who is she? She is my teacher. = Qui est-elle ? C’est ma professeure.", 'french': "Qui est-elle ? C’est ma professeure.", 'question': "Comment demander « Qui est-elle ? »", 'options': <String>["Who is she?", "Where she?", "What she is?"], 'answer': 0, 'correction': "La structure est Who + is + she.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L15", 'level': 'A1', 'title': "Décrire avec tall et short", 'subtitle': "Sous-chapitre 4 • Leçon 15/50", 'explanation': "Tall signifie grand en taille ; short signifie petit ou de petite taille. Le contexte aide à comprendre le sens.", 'example': "He is tall. = Il est grand. / She is short. = Elle est petite.", 'french': "Elle est petite.", 'question': "Quel est le contraire de tall ?", 'options': <String>["long", "short", "wide"], 'answer': 1, 'correction': "Short est l’opposé de tall pour la taille d’une personne.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L16", 'level': 'A1', 'title': "Décrire avec young et old", 'subtitle': "Sous-chapitre 4 • Leçon 16/50", 'explanation': "Young signifie jeune ; old signifie vieux/âgé pour une personne ou ancien pour un objet. Le contexte est important.", 'example': "The boy is young. = Le garçon est jeune.", 'french': "Le garçon est jeune.", 'question': "Young signifie…", 'options': <String>["Jeune", "Grand", "Rapide"], 'answer': 0, 'correction': "Young décrit un âge jeune.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L17", 'level': 'A1', 'title': "Décrire avec kind et friendly", 'subtitle': "Sous-chapitre 4 • Leçon 17/50", 'explanation': "Kind signifie gentil ou bienveillant ; friendly signifie amical. Ces adjectifs décrivent le comportement d’une personne.", 'example': "My teacher is kind. = Mon professeur est gentil.", 'french': "Mon professeur est gentil.", 'question': "Friendly signifie…", 'options': <String>["Amical", "Cher", "Fatigué"], 'answer': 0, 'correction': "Friendly décrit quelqu’un de sympathique ou amical.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L18", 'level': 'A1', 'title': "Décrire avec happy et sad", 'subtitle': "Sous-chapitre 4 • Leçon 18/50", 'explanation': "Happy signifie heureux ou content ; sad signifie triste. Ces adjectifs peuvent suivre le verbe be.", 'example': "I’m happy. = Je suis content. / He is sad. = Il est triste.", 'french': "Il est triste.", 'question': "Quel est le contraire de happy ?", 'options': <String>["sad", "tall", "kind"], 'answer': 0, 'correction': "Sad signifie triste.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L19", 'level': 'A1', 'title': "Décrire avec tired et excited", 'subtitle': "Sous-chapitre 4 • Leçon 19/50", 'explanation': "Tired signifie fatigué ; excited signifie enthousiaste ou très content à l’idée de quelque chose. Ces adjectifs décrivent un état.", 'example': "I’m tired after school. = Je suis fatigué après l’école.", 'french': "Je suis fatigué après l’école.", 'question': "Excited signifie…", 'options': <String>["En colère", "Enthousiaste", "Endormi uniquement"], 'answer': 1, 'correction': "Excited décrit un état d’enthousiasme.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L20", 'level': 'A1', 'title': "Décrire avec quiet et funny", 'subtitle': "Sous-chapitre 4 • Leçon 20/50", 'explanation': "Quiet signifie calme ou silencieux ; funny signifie drôle. Funny peut décrire une personne ou une situation amusante.", 'example': "My brother is funny. = Mon frère est drôle.", 'french': "Mon frère est drôle.", 'question': "Funny signifie…", 'options': <String>["Drôle", "Triste", "Silencieux"], 'answer': 0, 'correction': "Funny signifie drôle ; quiet signifie calme ou silencieux.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L21", 'level': 'A1', 'title': "Couleurs principales", 'subtitle': "Sous-chapitre 4 • Leçon 21/50", 'explanation': "Apprends les couleurs courantes : red, blue, yellow, green, black, white, orange, pink, purple et brown.", 'example': "The bag is blue. = Le sac est bleu.", 'french': "Le sac est bleu.", 'question': "Quelle couleur signifie green ?", 'options': <String>["Vert", "Gris", "Rouge"], 'answer': 0, 'correction': "Green signifie vert.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L22", 'level': 'A1', 'title': "Light blue et dark blue", 'subtitle': "Sous-chapitre 4 • Leçon 22/50", 'explanation': "Light blue signifie bleu clair ; dark blue signifie bleu foncé. Light et dark peuvent précéder plusieurs couleurs.", 'example': "My shirt is light blue. = Ma chemise est bleu clair.", 'french': "Ma chemise est bleu clair.", 'question': "Dark blue signifie…", 'options': <String>["Bleu clair", "Bleu foncé", "Vert foncé"], 'answer': 1, 'correction': "Dark signifie foncé dans ce contexte.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L23", 'level': 'A1', 'title': "Décrire la couleur d’un objet", 'subtitle': "Sous-chapitre 4 • Leçon 23/50", 'explanation': "Pour indiquer une couleur, utilise sujet + be + couleur ou couleur + nom : The car is red ; a red car.", 'example': "The car is red. = La voiture est rouge.", 'french': "La voiture est rouge.", 'question': "Quelle phrase est correcte ?", 'options': <String>["The red is car.", "The car is red.", "The car red are."], 'answer': 1, 'correction': "L’adjectif couleur peut suivre be ou précéder le nom.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L24", 'level': 'A1', 'title': "Formes simples", 'subtitle': "Sous-chapitre 4 • Leçon 24/50", 'explanation': "Les formes courantes sont circle (cercle), square (carré), triangle (triangle) et rectangle (rectangle).", 'example': "The sign is a circle. = Le panneau est un cercle.", 'french': "Le panneau est un cercle.", 'question': "Triangle signifie…", 'options': <String>["Cercle", "Triangle", "Carré"], 'answer': 1, 'correction': "Triangle désigne une forme à trois côtés.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L25", 'level': 'A1', 'title': "Tailles small, medium et large", 'subtitle': "Sous-chapitre 4 • Leçon 25/50", 'explanation': "Small signifie petit ; medium signifie moyen ; large signifie grand ou large selon l’objet. Ces mots décrivent la taille.", 'example': "I need a small shirt. = J’ai besoin d’un petit T-shirt.", 'french': "J’ai besoin d’un petit T-shirt.", 'question': "Medium signifie…", 'options': <String>["Petit", "Moyen", "Très grand"], 'answer': 1, 'correction': "Medium signifie moyen.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L26", 'level': 'A1', 'title': "Décrire la taille d’un objet", 'subtitle': "Sous-chapitre 4 • Leçon 26/50", 'explanation': "Pour décrire un objet, place l’adjectif avant le nom ou après be. L’adjectif ne prend pas de -s au pluriel dans ces exemples.", 'example': "a large bag = un grand sac ; The bags are large. = Les sacs sont grands.", 'french': "un grand sac ; The bags are large. = Les sacs sont grands.", 'question': "Quelle expression est correcte ?", 'options': <String>["two larges bags", "two large bags", "two bag large"], 'answer': 1, 'correction': "L’adjectif large reste invariable.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L27", 'level': 'A1', 'title': "Objets de la classe", 'subtitle': "Sous-chapitre 4 • Leçon 27/50", 'explanation': "Les objets courants comprennent book, pen, pencil, notebook, desk, chair et board. Apprends-les avec une image ou en les montrant autour de toi.", 'example': "This is a pencil. = C’est un crayon.", 'french': "C’est un crayon.", 'question': "Pencil signifie…", 'options': <String>["Stylo", "Crayon", "Cahier"], 'answer': 1, 'correction': "Pencil signifie crayon.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L28", 'level': 'A1', 'title': "Objets portables du quotidien", 'subtitle': "Sous-chapitre 4 • Leçon 28/50", 'explanation': "Les objets personnels incluent phone, keys, wallet, bag et bottle. Utilise my/your pour indiquer à qui ils appartiennent.", 'example': "My phone is here. = Mon téléphone est ici.", 'french': "Mon téléphone est ici.", 'question': "Keys signifie…", 'options': <String>["Clés", "Chaussures", "Livres"], 'answer': 0, 'correction': "Keys est le pluriel de key.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L29", 'level': 'A1', 'title': "Objets dans un sac", 'subtitle': "Sous-chapitre 4 • Leçon 29/50", 'explanation': "Pour décrire ce qu’il y a dans un sac, utilise There is pour un élément et There are pour plusieurs ; cette structure sera approfondie plus tard.", 'example': "There is a book in my bag. = Il y a un livre dans mon sac.", 'french': "Il y a un livre dans mon sac.", 'question': "Quel objet peut-on trouver in a bag ?", 'options': <String>["book", "sky", "mountain"], 'answer': 0, 'correction': "Book signifie livre.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L30", 'level': 'A1', 'title': "Dire This is my phone", 'subtitle': "Sous-chapitre 4 • Leçon 30/50", 'explanation': "This is my… présente un objet proche et indique qu’il appartient au locuteur avec my.", 'example': "This is my phone. = Voici mon téléphone.", 'french': "Voici mon téléphone.", 'question': "Que signifie This is my phone ?", 'options': <String>["Voici mon téléphone", "Où est mon téléphone ?", "Je téléphone maintenant"], 'answer': 0, 'correction': "This is présente l’objet ; my indique la possession.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L31", 'level': 'A1', 'title': "Vêtements de base", 'subtitle': "Sous-chapitre 4 • Leçon 31/50", 'explanation': "Les vêtements courants incluent shirt, T-shirt, trousers, jeans, dress, skirt et jacket.", 'example': "I have a blue jacket. = J’ai une veste bleue.", 'french': "J’ai une veste bleue.", 'question': "Jacket signifie…", 'options': <String>["Veste", "Chapeau", "Chaussette"], 'answer': 0, 'correction': "Jacket désigne une veste.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L32", 'level': 'A1', 'title': "Shirt et T-shirt", 'subtitle': "Sous-chapitre 4 • Leçon 32/50", 'explanation': "Shirt désigne une chemise ; T-shirt désigne un tee-shirt. En anglais américain, shirt peut être utilisé plus largement, mais ces distinctions sont utiles aux débutants.", 'example': "He is wearing a white shirt. = Il porte une chemise blanche.", 'french': "Il porte une chemise blanche.", 'question': "T-shirt signifie…", 'options': <String>["Tee-shirt", "Pantalon", "Chaussure"], 'answer': 0, 'correction': "T-shirt est un vêtement à manches courtes en général.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L33", 'level': 'A1', 'title': "Trousers et jeans", 'subtitle': "Sous-chapitre 4 • Leçon 33/50", 'explanation': "Trousers signifie pantalon en anglais britannique ; pants est le mot habituel en anglais américain. Jeans désigne un jean.", 'example': "I’m wearing jeans. = Je porte un jean.", 'french': "Je porte un jean.", 'question': "Quel mot est très courant en anglais américain pour « pantalon » ?", 'options': <String>["pants", "trousers only", "shorts always"], 'answer': 0, 'correction': "Pants est le mot américain courant pour pantalon.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L34", 'level': 'A1', 'title': "Shoes et socks", 'subtitle': "Sous-chapitre 4 • Leçon 34/50", 'explanation': "Shoes signifie chaussures ; socks signifie chaussettes. Ces noms sont souvent utilisés au pluriel en anglais.", 'example': "My shoes are black. = Mes chaussures sont noires.", 'french': "Mes chaussures sont noires.", 'question': "Socks signifie…", 'options': <String>["Chaussettes", "Chaussures", "Gants"], 'answer': 0, 'correction': "Socks signifie chaussettes.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L35", 'level': 'A1', 'title': "Jacket et coat", 'subtitle': "Sous-chapitre 4 • Leçon 35/50", 'explanation': "Jacket désigne une veste ; coat désigne généralement un manteau plus couvrant. L’usage dépend du vêtement et de la météo.", 'example': "Wear your coat. = Mets ton manteau.", 'french': "Mets ton manteau.", 'question': "Coat signifie le plus souvent…", 'options': <String>["Manteau", "Chemise", "Short"], 'answer': 0, 'correction': "Coat est un manteau.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L36", 'level': 'A1', 'title': "Dire I’m wearing", 'subtitle': "Sous-chapitre 4 • Leçon 36/50", 'explanation': "I’m wearing signifie « je porte » un vêtement maintenant. La structure est be + wearing, forme en -ing de wear.", 'example': "I’m wearing a blue shirt. = Je porte une chemise bleue.", 'french': "Je porte une chemise bleue.", 'question': "Complète : I’m ___ a jacket.", 'options': <String>["wear", "wearing", "wore"], 'answer': 1, 'correction': "Après am, la forme continue est wearing.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L37", 'level': 'A1', 'title': "Décrire les cheveux", 'subtitle': "Sous-chapitre 4 • Leçon 37/50", 'explanation': "Pour décrire les cheveux, on peut dire long hair, short hair, curly hair ou straight hair. Hair est généralement indénombrable dans cet usage.", 'example': "She has curly hair. = Elle a les cheveux bouclés.", 'french': "Elle a les cheveux bouclés.", 'question': "Curly hair signifie…", 'options': <String>["Cheveux bouclés", "Cheveux courts", "Cheveux gris"], 'answer': 0, 'correction': "Curly signifie bouclé.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L38", 'level': 'A1', 'title': "Parties du visage", 'subtitle': "Sous-chapitre 4 • Leçon 38/50", 'explanation': "Les parties du visage incluent eyes, ears, nose, mouth et teeth. Les images aident à mémoriser le vocabulaire.", 'example': "He has brown eyes. = Il a les yeux marron.", 'french': "Il a les yeux marron.", 'question': "Nose signifie…", 'options': <String>["Nez", "Oreille", "Bouche"], 'answer': 0, 'correction': "Nose signifie nez.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L39", 'level': 'A1', 'title': "Head, hand et foot", 'subtitle': "Sous-chapitre 4 • Leçon 39/50", 'explanation': "Head signifie tête ; hand signifie main ; foot signifie pied. Au pluriel, foot devient feet et tooth devient teeth.", 'example': "My foot hurts. = Mon pied me fait mal. / Wash your hands. = Lave-toi les mains.", 'french': "Lave-toi les mains.", 'question': "Quel est le pluriel de foot ?", 'options': <String>["foots", "feet", "footes"], 'answer': 1, 'correction': "Foot est irrégulier : foot–feet.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L40", 'level': 'A1', 'title': "Parties du corps avec images", 'subtitle': "Sous-chapitre 4 • Leçon 40/50", 'explanation': "Associe les mots aux parties du corps : arm, leg, knee, shoulder, back et stomach. Les illustrations doivent être anatomiquement claires et adaptées aux débutants.", 'example': "My arm hurts. = J’ai mal au bras.", 'french': "J’ai mal au bras.", 'question': "Leg signifie…", 'options': <String>["Jambe", "Bras", "Tête"], 'answer': 0, 'correction': "Leg signifie jambe.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L41", 'level': 'A1', 'title': "Possessif ’s", 'subtitle': "Sous-chapitre 4 • Leçon 41/50", 'explanation': "On ajoute souvent ’s après le nom d’une personne pour indiquer la possession : Anna’s bag signifie le sac d’Anna.", 'example': "This is Anna’s bag. = C’est le sac d’Anna.", 'french': "C’est le sac d’Anna.", 'question': "Anna’s bag signifie…", 'options': <String>["Le sac d’Anna", "Anna est dans un sac", "Le sac des Anna"], 'answer': 0, 'correction': "’s indique ici la possession.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L42", 'level': 'A1', 'title': "Distinguer his bag et her bag", 'subtitle': "Sous-chapitre 4 • Leçon 42/50", 'explanation': "His bag signifie son sac à lui ; her bag signifie son sac à elle. Le possessif dépend du possesseur, pas du sac.", 'example': "His bag is black. / Her bag is blue. = Son sac à lui est noir. / Son sac à elle est bleu.", 'french': "His bag is black. / Her bag is blue. = Son sac à lui est noir. / Son sac à elle est bleu.", 'question': "Pour parler du sac d’une fille, choisis…", 'options': <String>["his bag", "her bag", "she bag"], 'answer': 1, 'correction': "Her indique le possesseur féminin dans cet exemple.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L43", 'level': 'A1', 'title': "Question Whose is this?", 'subtitle': "Sous-chapitre 4 • Leçon 43/50", 'explanation': "Whose signifie à qui. Whose is this? demande à qui appartient un objet singulier proche.", 'example': "Whose is this? It’s my pen. = À qui est-ce ? C’est mon stylo.", 'french': "À qui est-ce ? C’est mon stylo.", 'question': "Whose demande…", 'options': <String>["À qui appartient cet objet", "Où est l’objet", "Quelle couleur est-ce"], 'answer': 0, 'correction': "Whose est le mot interrogatif de possession.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L44", 'level': 'A1', 'title': "Répondre It’s mine", 'subtitle': "Sous-chapitre 4 • Leçon 44/50", 'explanation': "Mine signifie le mien ou la mienne ; il remplace my + nom. On dit It’s mine, pas It’s my quand le nom n’est pas répété.", 'example': "Whose book is this? It’s mine. = À qui est ce livre ? Il est à moi.", 'french': "À qui est ce livre ? Il est à moi.", 'question': "Que signifie It’s mine ?", 'options': <String>["C’est mon livre (nom toujours nécessaire)", "C’est à moi", "C’est à toi"], 'answer': 1, 'correction': "Mine remplace le nom possédé dans la réponse.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L45", 'level': 'A1', 'title': "Mine et yours dans les objets", 'subtitle': "Sous-chapitre 4 • Leçon 45/50", 'explanation': "Mine signifie le mien/la mienne ; yours signifie le tien/la tienne ou le vôtre/la vôtre. Ces formes sont autonomes, sans nom après elles.", 'example': "This pen is mine. That pen is yours. = Ce stylo est à moi. Celui-là est à toi.", 'french': "Ce stylo est à moi. Celui-là est à toi.", 'question': "Yours signifie…", 'options': <String>["Le mien", "Le tien / le vôtre", "Le leur uniquement"], 'answer': 1, 'correction': "Yours est un possessif autonome.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L46", 'level': 'A1', 'title': "Décrire deux objets", 'subtitle': "Sous-chapitre 4 • Leçon 46/50", 'explanation': "Pour comparer ou décrire deux objets, réutilise les couleurs, tailles et noms. And relie deux éléments dans la même phrase.", 'example': "The bag is small and blue. The book is large and red. = Le sac est petit et bleu. Le livre est grand et rouge.", 'french': "Le sac est petit et bleu. Le livre est grand et rouge.", 'question': "And signifie…", 'options': <String>["Mais", "Et", "Ou"], 'answer': 1, 'correction': "And relie des mots ou des idées.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L47", 'level': 'A1', 'title': "Relier des descriptions avec and", 'subtitle': "Sous-chapitre 4 • Leçon 47/50", 'explanation': "And signifie et. Il relie des mots ou des phrases de même rôle. Il ne change pas la forme des adjectifs.", 'example': "She is kind and funny. = Elle est gentille et drôle.", 'french': "Elle est gentille et drôle.", 'question': "Quel mot signifie « et » ?", 'options': <String>["but", "and", "because"], 'answer': 1, 'correction': "And relie les deux adjectifs.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L48", 'level': 'A1', 'title': "Opposer des descriptions avec but", 'subtitle': "Sous-chapitre 4 • Leçon 48/50", 'explanation': "But signifie mais et sert à opposer deux idées. Il aide à créer des phrases plus naturelles et précises.", 'example': "He is young but very tall. = Il est jeune mais très grand.", 'french': "Il est jeune mais très grand.", 'question': "But signifie…", 'options': <String>["Parce que", "Mais", "Alors"], 'answer': 1, 'correction': "But introduit un contraste.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L49", 'level': 'A1', 'title': "Lire une carte de profil", 'subtitle': "Sous-chapitre 4 • Leçon 49/50", 'explanation': "Une carte de profil peut indiquer name, age, country, languages et hobbies. Lis les étiquettes puis repère les informations clés.", 'example': "Name: Alex. Age: 15. Country: Canada. Hobby: football.", 'french': "Name: Alex. Age: 15. Country: Canada. Hobby: football.", 'question': "Hobby signifie…", 'options': <String>["Passeport", "Loisir", "Adresse"], 'answer': 1, 'correction': "Hobby signifie loisir ou activité favorite.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L50", 'level': 'A1', 'title': "Révision : décrire trois personnes", 'subtitle': "Sous-chapitre 4 • Leçon 50/50", 'explanation': "Réutilise les membres de famille, les pronoms, les adjectifs, les vêtements et les couleurs. Évite les phrases isolées : relie-les pour décrire clairement.", 'example': "This is Mia. She is young and friendly. She has curly hair. She is wearing a red shirt. = Voici Mia. Elle est jeune et amicale. Elle a les cheveux bouclés. Elle porte une chemise rouge.", 'french': "Voici Mia. Elle est jeune et amicale. Elle a les cheveux bouclés. Elle porte une chemise rouge.", 'question': "Quelle phrase est correcte ?", 'options': <String>["She are friendly.", "She is friendly.", "She friendly is."], 'answer': 1, 'correction': "Avec she, on utilise is avant l’adjectif.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L01", 'level': 'A1', 'title': "Sept jours de la semaine", 'subtitle': "Sous-chapitre 5 • Leçon 1/50", 'explanation': "Les jours sont Monday, Tuesday, Wednesday, Thursday, Friday, Saturday et Sunday. En anglais, le nom des jours commence par une majuscule.", 'example': "Monday = lundi ; Sunday = dimanche.", 'french': "lundi ; Sunday = dimanche.", 'question': "Which day means « lundi »?", 'options': <String>["Monday", "Sunday", "Friday"], 'answer': 0, 'correction': "Monday signifie lundi.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L02", 'level': 'A1', 'title': "Douze mois", 'subtitle': "Sous-chapitre 5 • Leçon 2/50", 'explanation': "Les mois commencent par une majuscule : January, February, March, April, May, June, July, August, September, October, November, December.", 'example': "January = janvier ; December = décembre.", 'french': "janvier ; December = décembre.", 'question': "Which month means « août »?", 'options': <String>["April", "August", "October"], 'answer': 1, 'correction': "August signifie août.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L03", 'level': 'A1', 'title': "Saisons de l’année", 'subtitle': "Sous-chapitre 5 • Leçon 3/50", 'explanation': "Les saisons sont spring (printemps), summer (été), fall ou autumn (automne) et winter (hiver). Fall est courant en anglais américain.", 'example': "Summer is hot. = L’été est chaud.", 'french': "L’été est chaud.", 'question': "Fall signifie…", 'options': <String>["Printemps", "Automne", "Hiver"], 'answer': 1, 'correction': "Fall est le mot américain courant pour automne.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L04", 'level': 'A1', 'title': "Question What day is it?", 'subtitle': "Sous-chapitre 5 • Leçon 4/50", 'explanation': "What day is it? demande quel jour nous sommes. On répond It’s Monday ou Today is Monday.", 'example': "What day is it? — It’s Tuesday. = Quel jour sommes-nous ? — Mardi.", 'french': "Quel jour sommes-nous ? — Mardi.", 'question': "Quelle question demande le jour de la semaine ?", 'options': <String>["What day is it?", "What time is it?", "What month is it?"], 'answer': 0, 'correction': "Day signifie jour.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L05", 'level': 'A1', 'title': "Dire la date simplement", 'subtitle': "Sous-chapitre 5 • Leçon 5/50", 'explanation': "Pour donner une date, on peut dire It’s October 26th ou Today is October 26th. Les dates américaines placent souvent le mois avant le jour.", 'example': "Today is May 5th. = Nous sommes le 5 mai.", 'french': "Nous sommes le 5 mai.", 'question': "Dans une date américaine courante, qu’est-ce qui vient souvent en premier ?", 'options': <String>["Le mois", "L’année seulement", "Le jour de la semaine"], 'answer': 0, 'correction': "Le format courant américain place le mois avant le jour.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L06", 'level': 'A1', 'title': "Nombres ordinaux dans les dates", 'subtitle': "Sous-chapitre 5 • Leçon 6/50", 'explanation': "Les dates utilisent des nombres ordinaux : first, second, third, fourth, fifth. Les abréviations sont 1st, 2nd, 3rd, 4th, 5th.", 'example': "May first = le premier mai.", 'french': "le premier mai.", 'question': "Comment dit-on 2nd ?", 'options': <String>["second", "two", "twoth"], 'answer': 0, 'correction': "Second est l’ordinal de two.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L07", 'level': 'A1', 'title': "Dire l’heure pile", 'subtitle': "Sous-chapitre 5 • Leçon 7/50", 'explanation': "Pour l’heure pile, utilise It’s + heure + o’clock. O’clock s’utilise quand on indique une heure entière.", 'example': "It’s seven o’clock. = Il est sept heures.", 'french': "Il est sept heures.", 'question': "Comment dire « Il est huit heures » ?", 'options': <String>["It’s eight o’clock.", "It has eight hour.", "Eight clock it."], 'answer': 0, 'correction': "La structure est It’s + nombre + o’clock.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L08", 'level': 'A1', 'title': "Dire l’heure et les minutes", 'subtitle': "Sous-chapitre 5 • Leçon 8/50", 'explanation': "Pour une heure numérique, on peut lire les chiffres : It’s three fifteen ou It’s 3:15. Quarter past et half past sont d’autres formes courantes.", 'example': "It’s 6:30. = Il est 6 h 30.", 'french': "Il est 6 h 30.", 'question': "3:15 peut se dire…", 'options': <String>["three fifteen", "three fifty", "thirty three"], 'answer': 0, 'correction': "Pour les minutes, on peut lire l’heure puis les minutes.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L09", 'level': 'A1', 'title': "Question What time is it?", 'subtitle': "Sous-chapitre 5 • Leçon 9/50", 'explanation': "What time is it? demande l’heure. La réponse commence souvent par It’s…", 'example': "What time is it? — It’s nine o’clock. = Quelle heure est-il ? — Il est neuf heures.", 'french': "Quelle heure est-il ? — Il est neuf heures.", 'question': "Quelle question demande l’heure ?", 'options': <String>["What time is it?", "What day is it?", "Where is it?"], 'answer': 0, 'correction': "Time signifie heure ou temps selon le contexte.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L10", 'level': 'A1', 'title': "Utiliser at avec une heure", 'subtitle': "Sous-chapitre 5 • Leçon 10/50", 'explanation': "At sert souvent à indiquer une heure précise : at seven, at 8:30, at noon. Il faut apprendre cette préposition avec les expressions de temps.", 'example': "The class starts at eight. = Le cours commence à huit heures.", 'french': "Le cours commence à huit heures.", 'question': "The bus leaves ___ 7:30.", 'options': <String>["in", "on", "at"], 'answer': 2, 'correction': "At s’utilise pour une heure précise.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L11", 'level': 'A1', 'title': "In the morning", 'subtitle': "Sous-chapitre 5 • Leçon 11/50", 'explanation': "In the morning signifie le matin. On dit in the morning, in the afternoon et in the evening pour les parties de la journée.", 'example': "I study in the morning. = J’étudie le matin.", 'french': "J’étudie le matin.", 'question': "Comment dire « le matin » ?", 'options': <String>["at the morning", "in the morning", "on morning"], 'answer': 1, 'correction': "La préposition courante est in.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L12", 'level': 'A1', 'title': "In the afternoon", 'subtitle': "Sous-chapitre 5 • Leçon 12/50", 'explanation': "In the afternoon signifie l’après-midi. Utilise cette expression pour situer une activité dans la journée.", 'example': "I play football in the afternoon. = Je joue au football l’après-midi.", 'french': "Je joue au football l’après-midi.", 'question': "Comment dire « l’après-midi » ?", 'options': <String>["in the afternoon", "on the afternoon", "at afternoon"], 'answer': 0, 'correction': "On utilise in the afternoon.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L13", 'level': 'A1', 'title': "In the evening", 'subtitle': "Sous-chapitre 5 • Leçon 13/50", 'explanation': "In the evening signifie le soir, pour parler d’une période de la journée. Good evening est une salutation, ce qui est un usage différent.", 'example': "I read in the evening. = Je lis le soir.", 'french': "Je lis le soir.", 'question': "Quel groupe de mots signifie « le soir » ?", 'options': <String>["at evening", "in the evening", "on evening"], 'answer': 1, 'correction': "On dit in the evening pour la période de la journée.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L14", 'level': 'A1', 'title': "Distinguer at night et in the night", 'subtitle': "Sous-chapitre 5 • Leçon 14/50", 'explanation': "At night est la formule générale pour parler de la nuit. In the night insiste souvent sur quelque chose qui arrive pendant la nuit.", 'example': "I sleep at night. = Je dors la nuit.", 'french': "Je dors la nuit.", 'question': "Quelle expression est la plus naturelle pour une habitude générale ?", 'options': <String>["at night", "on night", "in nights"], 'answer': 0, 'correction': "At night est l’expression courante pour une habitude nocturne.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L15", 'level': 'A1', 'title': "Today, tomorrow et yesterday", 'subtitle': "Sous-chapitre 5 • Leçon 15/50", 'explanation': "Today signifie aujourd’hui, tomorrow demain et yesterday hier. Ces mots permettent de situer une action dans le temps.", 'example': "I’m busy today. = Je suis occupé aujourd’hui.", 'french': "Je suis occupé aujourd’hui.", 'question': "Tomorrow signifie…", 'options': <String>["Hier", "Demain", "Aujourd’hui"], 'answer': 1, 'correction': "Tomorrow signifie demain.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L16", 'level': 'A1', 'title': "This week et next week", 'subtitle': "Sous-chapitre 5 • Leçon 16/50", 'explanation': "This week signifie cette semaine ; next week signifie la semaine prochaine. Last week signifie la semaine dernière.", 'example': "I have an exam next week. = J’ai un examen la semaine prochaine.", 'french': "J’ai un examen la semaine prochaine.", 'question': "Next week signifie…", 'options': <String>["La semaine dernière", "Cette semaine", "La semaine prochaine"], 'answer': 2, 'correction': "Next indique ici la période suivante.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L17", 'level': 'A1', 'title': "Last week et next month", 'subtitle': "Sous-chapitre 5 • Leçon 17/50", 'explanation': "Last week signifie la semaine dernière ; next month signifie le mois prochain. Last renvoie à la période passée et next à la suivante.", 'example': "I travelled last week. = J’ai voyagé la semaine dernière.", 'french': "J’ai voyagé la semaine dernière.", 'question': "Next month signifie…", 'options': <String>["Le mois dernier", "Le mois prochain", "Ce mois-ci"], 'answer': 1, 'correction': "Next month désigne le mois suivant.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L18", 'level': 'A1', 'title': "Parler d’un anniversaire", 'subtitle': "Sous-chapitre 5 • Leçon 18/50", 'explanation': "Birthday signifie anniversaire de naissance. Pour demander la date, utilise When is your birthday? Pour répondre, dis My birthday is in May ou My birthday is on May 5th.", 'example': "My birthday is in June. = Mon anniversaire est en juin.", 'french': "Mon anniversaire est en juin.", 'question': "Birthday signifie…", 'options': <String>["Anniversaire de naissance", "Mariage", "Vacances"], 'answer': 0, 'correction': "Birthday désigne l’anniversaire de naissance.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L19", 'level': 'A1', 'title': "Question When is your birthday?", 'subtitle': "Sous-chapitre 5 • Leçon 19/50", 'explanation': "When demande quand. Pour la date d’anniversaire, demande When is your birthday? La réponse peut donner un mois ou une date précise.", 'example': "When is your birthday? — It’s in April. = Quand est ton anniversaire ? — En avril.", 'french': "Quand est ton anniversaire ? — En avril.", 'question': "Quelle question demande la date d’anniversaire ?", 'options': <String>["When is your birthday?", "Where is your birthday?", "Who is your birthday?"], 'answer': 0, 'correction': "When signifie quand.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L20", 'level': 'A1', 'title': "Prendre un rendez-vous simple", 'subtitle': "Sous-chapitre 5 • Leçon 20/50", 'explanation': "Pour proposer un rendez-vous, tu peux demander Are you free on Friday? ou Can we meet at three? Utilise at pour l’heure et on pour le jour.", 'example': "Can we meet at three? = Peut-on se voir à trois heures ?", 'french': "Peut-on se voir à trois heures ?", 'question': "Quelle préposition convient avant Friday ?", 'options': <String>["on", "at", "in"], 'answer': 0, 'correction': "On s’utilise couramment avec les jours.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L21", 'level': 'A1', 'title': "Wake up dans une routine", 'subtitle': "Sous-chapitre 5 • Leçon 21/50", 'explanation': "Wake up signifie se réveiller. Pour parler d’une habitude, utilise le présent simple : I wake up at six.", 'example': "I wake up at six every day. = Je me réveille à six heures chaque jour.", 'french': "Je me réveille à six heures chaque jour.", 'question': "Wake up signifie…", 'options': <String>["Se coucher", "Se réveiller", "Déjeuner"], 'answer': 1, 'correction': "Wake up décrit le passage du sommeil à l’éveil.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L22", 'level': 'A1', 'title': "Get up dans une routine", 'subtitle': "Sous-chapitre 5 • Leçon 22/50", 'explanation': "Get up signifie se lever du lit. Wake up signifie se réveiller ; les deux actions peuvent arriver à des moments différents.", 'example': "I wake up at six and get up at six fifteen. = Je me réveille à six heures et je me lève à six heures quinze.", 'french': "Je me réveille à six heures et je me lève à six heures quinze.", 'question': "Get up signifie…", 'options': <String>["Se lever du lit", "Se réveiller seulement", "S’endormir"], 'answer': 0, 'correction': "Get up décrit le fait de se lever.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L23", 'level': 'A1', 'title': "Parler du petit-déjeuner", 'subtitle': "Sous-chapitre 5 • Leçon 23/50", 'explanation': "Breakfast signifie petit-déjeuner. On dit have breakfast pour prendre le petit-déjeuner ; on ne traduit pas chaque mot séparément.", 'example': "I have breakfast at seven. = Je prends le petit-déjeuner à sept heures.", 'french': "Je prends le petit-déjeuner à sept heures.", 'question': "Comment dire « prendre le petit-déjeuner » ?", 'options': <String>["make breakfast always", "have breakfast", "eat morning"], 'answer': 1, 'correction': "Have breakfast est l’expression courante.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L24", 'level': 'A1', 'title': "Partir à l’école ou au travail", 'subtitle': "Sous-chapitre 5 • Leçon 24/50", 'explanation': "Go to school signifie aller à l’école ; go to work signifie aller au travail. On utilise go to + lieu dans ces expressions.", 'example': "I go to school at seven. = Je vais à l’école à sept heures.", 'french': "Je vais à l’école à sept heures.", 'question': "Comment dire « aller au travail » ?", 'options': <String>["go to work", "go work to", "go at work"], 'answer': 0, 'correction': "La structure est go to + lieu.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L25", 'level': 'A1', 'title': "Rentrer à la maison", 'subtitle': "Sous-chapitre 5 • Leçon 25/50", 'explanation': "Go home signifie rentrer ou aller à la maison. Dans cette expression, on n’utilise normalement pas to avant home.", 'example': "I go home after class. = Je rentre à la maison après les cours.", 'french': "Je rentre à la maison après les cours.", 'question': "Quelle phrase est correcte ?", 'options': <String>["I go to home.", "I go home.", "I goes home."], 'answer': 1, 'correction': "Home fonctionne ici comme un adverbe de direction.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L26", 'level': 'A1', 'title': "Parler du dîner", 'subtitle': "Sous-chapitre 5 • Leçon 26/50", 'explanation': "Dinner désigne le dîner ou le repas principal du soir selon le contexte. On dit have dinner pour prendre le dîner.", 'example': "We have dinner at seven. = Nous dînons à sept heures.", 'french': "Nous dînons à sept heures.", 'question': "Quelle expression signifie « dîner » comme activité ?", 'options': <String>["have dinner", "make night", "do dinner always"], 'answer': 0, 'correction': "Have dinner est l’expression naturelle.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L27", 'level': 'A1', 'title': "Décrire la routine du soir", 'subtitle': "Sous-chapitre 5 • Leçon 27/50", 'explanation': "Pour raconter la routine du soir, enchaîne des verbes au présent simple et des expressions de temps : have dinner, study, relax, go to bed.", 'example': "I study, relax and go to bed at ten. = J’étudie, je me détends et je me couche à dix heures.", 'french': "J’étudie, je me détends et je me couche à dix heures.", 'question': "Quelle expression signifie « se coucher » ?", 'options': <String>["go to bed", "get up", "wake up"], 'answer': 0, 'correction': "Go to bed signifie aller se coucher.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L28", 'level': 'A1', 'title': "First, then et finally", 'subtitle': "Sous-chapitre 5 • Leçon 28/50", 'explanation': "First signifie d’abord ; then signifie ensuite ; finally signifie enfin. Ces mots organisent les étapes d’une routine ou d’une histoire.", 'example': "First, I eat. Then, I study. Finally, I sleep. = D’abord je mange. Ensuite j’étudie. Enfin je dors.", 'french': "D’abord je mange. Ensuite j’étudie. Enfin je dors.", 'question': "Finally signifie…", 'options': <String>["D’abord", "Ensuite", "Enfin"], 'answer': 2, 'correction': "Finally introduit la dernière étape.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L29", 'level': 'A1', 'title': "Every day pour une habitude", 'subtitle': "Sous-chapitre 5 • Leçon 29/50", 'explanation': "Every day signifie chaque jour. On l’utilise souvent avec le présent simple pour parler d’une habitude répétée.", 'example': "I practise English every day. = Je pratique l’anglais chaque jour.", 'french': "Je pratique l’anglais chaque jour.", 'question': "Every day signifie…", 'options': <String>["Chaque jour", "Hier", "La semaine prochaine"], 'answer': 0, 'correction': "Every day indique une répétition quotidienne.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L30", 'level': 'A1', 'title': "Usually dans une routine", 'subtitle': "Sous-chapitre 5 • Leçon 30/50", 'explanation': "Usually signifie habituellement. Il se place souvent avant le verbe principal, mais après be : I usually study ; I am usually busy.", 'example': "I usually walk to school. = Je vais habituellement à l’école à pied.", 'french': "Je vais habituellement à l’école à pied.", 'question': "Usually signifie…", 'options': <String>["Jamais", "Habituellement", "Demain"], 'answer': 1, 'correction': "Usually exprime une fréquence habituelle.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L31", 'level': 'A1', 'title': "Sometimes pour la fréquence", 'subtitle': "Sous-chapitre 5 • Leçon 31/50", 'explanation': "Sometimes signifie parfois. Il se place souvent avant le verbe principal ou au début/à la fin de la phrase.", 'example': "I sometimes play basketball. = Je joue parfois au basket.", 'french': "Je joue parfois au basket.", 'question': "Sometimes signifie…", 'options': <String>["Toujours", "Parfois", "Jamais"], 'answer': 1, 'correction': "Sometimes indique que l’action arrive certaines fois.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L32", 'level': 'A1', 'title': "Never dans une phrase", 'subtitle': "Sous-chapitre 5 • Leçon 32/50", 'explanation': "Never signifie jamais. Il a déjà un sens négatif ; dans une phrase standard, on n’ajoute généralement pas don’t devant le même verbe pour exprimer la même négation.", 'example': "I never smoke. = Je ne fume jamais.", 'french': "Je ne fume jamais.", 'question': "Never signifie…", 'options': <String>["Toujours", "Parfois", "Jamais"], 'answer': 2, 'correction': "Never exprime une fréquence nulle.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L33", 'level': 'A1', 'title': "Always avec les routines", 'subtitle': "Sous-chapitre 5 • Leçon 33/50", 'explanation': "Always signifie toujours. Avec un verbe principal, il se place souvent avant ce verbe ; avec be, il vient généralement après be.", 'example': "I always brush my teeth. = Je me brosse toujours les dents.", 'french': "Je me brosse toujours les dents.", 'question': "Always signifie…", 'options': <String>["Toujours", "Parfois", "Rarement"], 'answer': 0, 'correction': "Always indique une fréquence constante.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L34", 'level': 'A1', 'title': "Placer often dans une phrase", 'subtitle': "Sous-chapitre 5 • Leçon 34/50", 'explanation': "Often signifie souvent. Il se place généralement avant le verbe principal, mais après be.", 'example': "I often read at night. = Je lis souvent la nuit.", 'french': "Je lis souvent la nuit.", 'question': "Complète : I ___ play football.", 'options': <String>["often", "am often play", "play often am"], 'answer': 0, 'correction': "Often précède généralement le verbe principal.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L35", 'level': 'A1', 'title': "Question How often?", 'subtitle': "Sous-chapitre 5 • Leçon 35/50", 'explanation': "How often? signifie à quelle fréquence ? On peut répondre avec always, usually, often, sometimes ou never.", 'example': "How often do you study? — Every day. = À quelle fréquence étudies-tu ? — Chaque jour.", 'french': "À quelle fréquence étudies-tu ? — Chaque jour.", 'question': "Quelle question demande la fréquence ?", 'options': <String>["How often?", "How old?", "How much?"], 'answer': 0, 'correction': "How often demande la fréquence d’une action.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L36", 'level': 'A1', 'title': "Before et after avec des activités", 'subtitle': "Sous-chapitre 5 • Leçon 36/50", 'explanation': "Before signifie avant ; after signifie après. Ils permettent d’ordonner des activités ou des moments.", 'example': "I study before dinner. = J’étudie avant le dîner.", 'french': "J’étudie avant le dîner.", 'question': "After signifie…", 'options': <String>["Avant", "Après", "Pendant"], 'answer': 1, 'correction': "After signifie après.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L37", 'level': 'A1', 'title': "Activité du week-end", 'subtitle': "Sous-chapitre 5 • Leçon 37/50", 'explanation': "Weekend signifie week-end. On dit on the weekend en anglais américain courant ; at the weekend est plus courant en anglais britannique.", 'example': "I play football on the weekend. = Je joue au football le week-end.", 'french': "Je joue au football le week-end.", 'question': "Quelle expression est courante en anglais américain ?", 'options': <String>["on the weekend", "in weekend", "at weekend only"], 'answer': 0, 'correction': "On the weekend est courant en anglais américain.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L38", 'level': 'A1', 'title': "Dire I’m early et I’m late", 'subtitle': "Sous-chapitre 5 • Leçon 38/50", 'explanation': "Early signifie en avance ou tôt ; late signifie en retard ou tard. Utilise be + early/late pour décrire une arrivée ou une heure.", 'example': "I’m early. = Je suis en avance. / I’m late. = Je suis en retard.", 'french': "Je suis en retard.", 'question': "Late signifie…", 'options': <String>["En avance", "En retard", "Prêt"], 'answer': 1, 'correction': "Late signifie en retard dans ce contexte.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L39", 'level': 'A1', 'title': "Dire l’heure d’un cours", 'subtitle': "Sous-chapitre 5 • Leçon 39/50", 'explanation': "Pour annoncer l’heure d’un cours, utilise The class starts at… ou My class is at…. At introduit l’heure précise.", 'example': "My class starts at nine. = Mon cours commence à neuf heures.", 'french': "Mon cours commence à neuf heures.", 'question': "Quelle préposition précède nine o’clock ?", 'options': <String>["at", "in", "on"], 'answer': 0, 'correction': "At introduit une heure précise.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L40", 'level': 'A1', 'title': "Lire un horaire quotidien", 'subtitle': "Sous-chapitre 5 • Leçon 40/50", 'explanation': "Un horaire indique les heures et les activités. Repère les verbes d’action, puis associe chaque activité à son heure.", 'example': "7:00 wake up; 8:00 class; 4:00 study. = 7 h réveil ; 8 h cours ; 16 h étude.", 'french': "7 h réveil ; 8 h cours ; 16 h étude.", 'question': "À 8:00, que fait la personne dans l’exemple ?", 'options': <String>["Wake up", "Class", "Study"], 'answer': 1, 'correction': "L’horaire associe 8:00 à class.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L41", 'level': 'A1', 'title': "Comprendre un calendrier simple", 'subtitle': "Sous-chapitre 5 • Leçon 41/50", 'explanation': "Un calendrier présente les jours et les dates. Repère le nom du mois, le jour de la semaine et le numéro de la date.", 'example': "The meeting is on Tuesday, May 12th. = La réunion est mardi 12 mai.", 'french': "La réunion est mardi 12 mai.", 'question': "Quel élément indique le jour de la semaine ?", 'options': <String>["Tuesday", "May", "12th"], 'answer': 0, 'correction': "Tuesday est le jour de la semaine.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L42", 'level': 'A1', 'title': "Dire la durée d’une activité", 'subtitle': "Sous-chapitre 5 • Leçon 42/50", 'explanation': "Pour parler de durée, utilise for + durée : for ten minutes, for two hours. Since indique plutôt le point de départ d’une durée qui continue.", 'example': "I study for one hour. = J’étudie pendant une heure.", 'french': "J’étudie pendant une heure.", 'question': "Quelle expression signifie « pendant deux heures » ?", 'options': <String>["for two hours", "at two hours", "in two hour"], 'answer': 0, 'correction': "For introduit une durée.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L43", 'level': 'A1', 'title': "From…to… pour une plage horaire", 'subtitle': "Sous-chapitre 5 • Leçon 43/50", 'explanation': "From…to… indique un début et une fin : from nine to ten. On l’utilise pour les cours, les horaires et les activités.", 'example': "I study from six to seven. = J’étudie de six à sept heures.", 'french': "J’étudie de six à sept heures.", 'question': "Comment dire « de neuf à dix heures » ?", 'options': <String>["from nine to ten", "at nine and ten", "in nine to ten"], 'answer': 0, 'correction': "From indique le début et to la fin.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L44", 'level': 'A1', 'title': "Inviter quelqu’un à une heure", 'subtitle': "Sous-chapitre 5 • Leçon 44/50", 'explanation': "Pour proposer une rencontre, dis Are you free at six? ou Let’s meet at six. At précède l’heure.", 'example': "Let’s meet at six. = Retrouvons-nous à six heures.", 'french': "Retrouvons-nous à six heures.", 'question': "Quelle préposition convient avant six o’clock ?", 'options': <String>["on", "at", "in"], 'answer': 1, 'correction': "At introduit l’heure du rendez-vous.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L45", 'level': 'A1', 'title': "Confirmer une heure", 'subtitle': "Sous-chapitre 5 • Leçon 45/50", 'explanation': "Pour confirmer, tu peux dire Yes, six works for me ou That’s fine. Pour demander une confirmation, dis Is six okay?", 'example': "Six works for me. = Six heures me conviennent.", 'french': "Six heures me conviennent.", 'question': "Quelle phrase confirme que l’heure convient ?", 'options': <String>["Six works for me.", "I six work.", "Six is yesterday."], 'answer': 0, 'correction': "Cette expression signifie que l’heure convient.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L46", 'level': 'A1', 'title': "Modifier un rendez-vous", 'subtitle': "Sous-chapitre 5 • Leçon 46/50", 'explanation': "Pour modifier l’heure, demande Can we meet later? ou Can we make it seven? Il est utile de proposer une nouvelle heure clairement.", 'example': "Can we meet at seven instead? = Peut-on se voir à sept heures à la place ?", 'french': "Peut-on se voir à sept heures à la place ?", 'question': "Instead signifie ici…", 'options': <String>["À la place", "Hier", "Toujours"], 'answer': 0, 'correction': "Instead indique une alternative.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L47", 'level': 'A1', 'title': "Dire I’m busy et I’m free", 'subtitle': "Sous-chapitre 5 • Leçon 47/50", 'explanation': "Busy signifie occupé ; free signifie libre ou disponible. Pour accepter une invitation, tu peux dire I’m free at six.", 'example': "I’m busy today. = Je suis occupé aujourd’hui.", 'french': "Je suis occupé aujourd’hui.", 'question': "Free signifie dans ce contexte…", 'options': <String>["Libre / disponible", "Cher", "Fatigué"], 'answer': 0, 'correction': "I’m free indique la disponibilité.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L48", 'level': 'A1', 'title': "Raconter une journée au présent simple", 'subtitle': "Sous-chapitre 5 • Leçon 48/50", 'explanation': "Le présent simple sert à parler d’habitudes. Utilise un sujet, un verbe et des marqueurs de fréquence ou de temps.", 'example': "I wake up at six, go to school and study in the evening. = Je me réveille à six heures, vais à l’école et étudie le soir.", 'french': "Je me réveille à six heures, vais à l’école et étudie le soir.", 'question': "Quel temps décrit une routine habituelle ?", 'options': <String>["Present simple", "Past continuous", "Future perfect"], 'answer': 0, 'correction': "Le présent simple sert notamment aux habitudes.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L49", 'level': 'A1', 'title': "Écouter et ordonner une routine", 'subtitle': "Sous-chapitre 5 • Leçon 49/50", 'explanation': "Pour remettre une routine en ordre, repère les mots de temps et la logique des activités : wake up, have breakfast, go to school, come home, go to bed.", 'example': "First I wake up. Then I have breakfast. Finally I go to school.", 'french': "First I wake up. Then I have breakfast. Finally I go to school.", 'question': "Quel mot indique la première étape ?", 'options': <String>["First", "Finally", "Yesterday"], 'answer': 0, 'correction': "First signifie d’abord.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L50", 'level': 'A1', 'title': "Révision : raconter sa journée", 'subtitle': "Sous-chapitre 5 • Leçon 50/50", 'explanation': "Réutilise les heures, les routines, les marqueurs de fréquence et les connecteurs temporels. Une bonne description contient plusieurs phrases reliées.", 'example': "I usually wake up at six. Then I have breakfast. I go to school at seven. = Je me réveille habituellement à six heures. Ensuite je prends le petit-déjeuner. Je vais à l’école à sept heures.", 'french': "Je me réveille habituellement à six heures. Ensuite je prends le petit-déjeuner. Je vais à l’école à sept heures.", 'question': "Quelle phrase est correcte ?", 'options': <String>["I usually wake up at six.", "I wake usually up six at.", "I am wake up every day."], 'answer': 0, 'correction': "Usually précède le verbe principal ; at introduit l’heure.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L01", 'level': 'A1', 'title': "House et apartment", 'subtitle': "Sous-chapitre 6 • Leçon 1/50", 'explanation': "House signifie maison ; apartment signifie appartement. En anglais américain, apartment est plus courant que flat.", 'example': "I live in an apartment. = J’habite dans un appartement.", 'french': "J’habite dans un appartement.", 'question': "Apartment signifie…", 'options': <String>["Appartement", "Jardin", "Cuisine"], 'answer': 0, 'correction': "Apartment signifie appartement.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L02", 'level': 'A1', 'title': "Pièces de la maison", 'subtitle': "Sous-chapitre 6 • Leçon 2/50", 'explanation': "Les pièces incluent living room, bedroom, kitchen, bathroom et dining room. Apprends-les en reliant chaque mot à une image.", 'example': "The bedroom is upstairs. = La chambre est à l’étage.", 'french': "La chambre est à l’étage.", 'question': "Bedroom signifie…", 'options': <String>["Cuisine", "Chambre", "Salon"], 'answer': 1, 'correction': "Bedroom est la chambre à coucher.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L03", 'level': 'A1', 'title': "Living room", 'subtitle': "Sous-chapitre 6 • Leçon 3/50", 'explanation': "Living room signifie salon, la pièce où l’on se détend ou reçoit des invités.", 'example': "We watch TV in the living room. = Nous regardons la télévision au salon.", 'french': "Nous regardons la télévision au salon.", 'question': "Living room signifie…", 'options': <String>["Salon", "Salle de bain", "Garage"], 'answer': 0, 'correction': "Living room est la pièce commune de détente.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L04", 'level': 'A1', 'title': "Bedroom", 'subtitle': "Sous-chapitre 6 • Leçon 4/50", 'explanation': "Bedroom signifie chambre à coucher. Bed signifie lit et room signifie pièce.", 'example': "My bedroom is small. = Ma chambre est petite.", 'french': "Ma chambre est petite.", 'question': "Bedroom signifie…", 'options': <String>["Chambre", "Cuisine", "Couloir"], 'answer': 0, 'correction': "Bedroom est la pièce où l’on dort.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L05", 'level': 'A1', 'title': "Kitchen", 'subtitle': "Sous-chapitre 6 • Leçon 5/50", 'explanation': "Kitchen signifie cuisine. On y prépare les repas ; kitchen peut être accompagné d’objets comme table, fridge et stove.", 'example': "The kitchen is clean. = La cuisine est propre.", 'french': "La cuisine est propre.", 'question': "Kitchen signifie…", 'options': <String>["Cuisine", "Salon", "Chambre"], 'answer': 0, 'correction': "Kitchen signifie cuisine.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L06", 'level': 'A1', 'title': "Bathroom", 'subtitle': "Sous-chapitre 6 • Leçon 6/50", 'explanation': "Bathroom signifie salle de bain ou toilettes selon le contexte régional. Restroom est aussi courant pour les toilettes publiques aux États-Unis.", 'example': "Where is the bathroom? = Où sont les toilettes ?", 'french': "Où sont les toilettes ?", 'question': "Quelle question demande où sont les toilettes ?", 'options': <String>["Where is the bathroom?", "What is the bathroom?", "Who bathroom?"], 'answer': 0, 'correction': "Where demande un lieu.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L07", 'level': 'A1', 'title': "Meubles essentiels", 'subtitle': "Sous-chapitre 6 • Leçon 7/50", 'explanation': "Furniture signifie meubles. Les meubles courants sont table, chair, bed, sofa, desk et shelf.", 'example': "There is a sofa in the living room. = Il y a un canapé dans le salon.", 'french': "Il y a un canapé dans le salon.", 'question': "Sofa signifie…", 'options': <String>["Canapé", "Lit", "Bureau"], 'answer': 0, 'correction': "Sofa signifie canapé.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L08", 'level': 'A1', 'title': "Table, chair et bed", 'subtitle': "Sous-chapitre 6 • Leçon 8/50", 'explanation': "Table signifie table ; chair signifie chaise ; bed signifie lit. Le contexte aide à distinguer table et desk, qui est un bureau de travail.", 'example': "The book is on the table. = Le livre est sur la table.", 'french': "Le livre est sur la table.", 'question': "Chair signifie…", 'options': <String>["Chaise", "Table", "Lit"], 'answer': 0, 'correction': "Chair signifie chaise.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L09", 'level': 'A1', 'title': "Appareils domestiques courants", 'subtitle': "Sous-chapitre 6 • Leçon 9/50", 'explanation': "Les appareils courants comprennent fridge (réfrigérateur), oven (four), washing machine (machine à laver) et fan (ventilateur).", 'example': "The food is in the fridge. = La nourriture est dans le réfrigérateur.", 'french': "La nourriture est dans le réfrigérateur.", 'question': "Fridge signifie…", 'options': <String>["Réfrigérateur", "Four", "Ventilateur"], 'answer': 0, 'correction': "Fridge est une forme courante de refrigerator.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L10", 'level': 'A1', 'title': "There is avec un objet", 'subtitle': "Sous-chapitre 6 • Leçon 10/50", 'explanation': "There is signifie il y a pour un élément singulier. La structure sert à dire qu’un objet ou une personne se trouve quelque part.", 'example': "There is a book on the table. = Il y a un livre sur la table.", 'french': "Il y a un livre sur la table.", 'question': "___ a chair in the room.", 'options': <String>["There is", "There are", "There am"], 'answer': 0, 'correction': "Un objet singulier prend there is.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L11", 'level': 'A1', 'title': "There are avec plusieurs objets", 'subtitle': "Sous-chapitre 6 • Leçon 11/50", 'explanation': "There are signifie il y a pour plusieurs éléments. Il s’accorde avec un nom pluriel.", 'example': "There are two chairs. = Il y a deux chaises.", 'french': "Il y a deux chaises.", 'question': "___ three books on the desk.", 'options': <String>["There is", "There are", "There am"], 'answer': 1, 'correction': "Three books est pluriel, donc there are.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L12", 'level': 'A1', 'title': "Négation there isn’t", 'subtitle': "Sous-chapitre 6 • Leçon 12/50", 'explanation': "There isn’t signifie il n’y a pas pour un élément singulier. La forme complète est there is not.", 'example': "There isn’t a TV in my room. = Il n’y a pas de télévision dans ma chambre.", 'french': "Il n’y a pas de télévision dans ma chambre.", 'question': "Quelle forme nie un objet singulier ?", 'options': <String>["There isn’t", "There aren’t", "There don’t"], 'answer': 0, 'correction': "There isn’t est la négation de there is.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L13", 'level': 'A1', 'title': "Question Is there…?", 'subtitle': "Sous-chapitre 6 • Leçon 13/50", 'explanation': "Pour demander s’il y a un objet singulier, inverse is et there : Is there a…? La réponse courte est Yes, there is ou No, there isn’t.", 'example': "Is there a bathroom? = Y a-t-il une salle de bain ?", 'french': "Y a-t-il une salle de bain ?", 'question': "Quelle question est correcte ?", 'options': <String>["There is a bathroom?", "Is there a bathroom?", "Does there a bathroom?"], 'answer': 1, 'correction': "Avec there is, la question commence par Is there.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L14", 'level': 'A1', 'title': "Question Are there…?", 'subtitle': "Sous-chapitre 6 • Leçon 14/50", 'explanation': "Are there…? sert à demander s’il y a plusieurs éléments. La réponse courte est Yes, there are ou No, there aren’t.", 'example': "Are there two bedrooms? = Y a-t-il deux chambres ?", 'french': "Y a-t-il deux chambres ?", 'question': "___ any chairs?", 'options': <String>["Is there", "Are there", "Does there"], 'answer': 1, 'correction': "Chairs est pluriel, donc Are there.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L15", 'level': 'A1', 'title': "In front of", 'subtitle': "Sous-chapitre 6 • Leçon 15/50", 'explanation': "In front of signifie devant. Cette expression de lieu contient trois mots et doit être apprise comme un groupe.", 'example': "The car is in front of the house. = La voiture est devant la maison.", 'french': "La voiture est devant la maison.", 'question': "In front of signifie…", 'options': <String>["Derrière", "Devant", "Entre"], 'answer': 1, 'correction': "In front of signifie devant.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L16", 'level': 'A1', 'title': "Behind", 'subtitle': "Sous-chapitre 6 • Leçon 16/50", 'explanation': "Behind signifie derrière. Il indique qu’un objet se trouve à l’arrière d’un autre.", 'example': "The cat is behind the sofa. = Le chat est derrière le canapé.", 'french': "Le chat est derrière le canapé.", 'question': "Behind signifie…", 'options': <String>["À côté", "Derrière", "Sur"], 'answer': 1, 'correction': "Behind signifie derrière.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L17", 'level': 'A1', 'title': "Next to", 'subtitle': "Sous-chapitre 6 • Leçon 17/50", 'explanation': "Next to signifie à côté de. Cette expression est utile pour localiser des objets ou donner des indications.", 'example': "The bank is next to the store. = La banque est à côté du magasin.", 'french': "La banque est à côté du magasin.", 'question': "Next to signifie…", 'options': <String>["À côté de", "Au-dessus de", "À l’intérieur de"], 'answer': 0, 'correction': "Next to signifie à côté de.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L18", 'level': 'A1', 'title': "Between", 'subtitle': "Sous-chapitre 6 • Leçon 18/50", 'explanation': "Between signifie entre deux éléments. Il est souvent suivi de deux noms reliés par and.", 'example': "The school is between the bank and the park. = L’école est entre la banque et le parc.", 'french': "L’école est entre la banque et le parc.", 'question': "Between signifie…", 'options': <String>["Entre", "Derrière", "Sous"], 'answer': 0, 'correction': "Between indique une position entre des éléments.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L19", 'level': 'A1', 'title': "Under et below", 'subtitle': "Sous-chapitre 6 • Leçon 19/50", 'explanation': "Under signifie sous, souvent directement en dessous ; below signifie plus bas que, sans forcément être directement dessous.", 'example': "The bag is under the table. = Le sac est sous la table.", 'french': "Le sac est sous la table.", 'question': "Under signifie…", 'options': <String>["Sous", "Sur", "Devant"], 'answer': 0, 'correction': "Under indique une position en dessous.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L20", 'level': 'A1', 'title': "Above et over", 'subtitle': "Sous-chapitre 6 • Leçon 20/50", 'explanation': "Above signifie au-dessus de. Over peut aussi signifier au-dessus, parfois avec l’idée de couvrir ou de traverser.", 'example': "The lamp is above the table. = La lampe est au-dessus de la table.", 'french': "La lampe est au-dessus de la table.", 'question': "Above signifie…", 'options': <String>["Au-dessus de", "À l’intérieur", "Entre"], 'answer': 0, 'correction': "Above décrit une position plus haute.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L21", 'level': 'A1', 'title': "Inside et outside", 'subtitle': "Sous-chapitre 6 • Leçon 21/50", 'explanation': "Inside signifie à l’intérieur ; outside signifie à l’extérieur. Ces mots peuvent servir de préposition ou d’adverbe selon la phrase.", 'example': "The children are outside. = Les enfants sont dehors.", 'french': "Les enfants sont dehors.", 'question': "Outside signifie…", 'options': <String>["À l’intérieur", "À l’extérieur", "À côté"], 'answer': 1, 'correction': "Outside signifie dehors ou à l’extérieur.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L22", 'level': 'A1', 'title': "Question Where is the…?", 'subtitle': "Sous-chapitre 6 • Leçon 22/50", 'explanation': "Where is the…? demande où se trouve un objet singulier. Réponds avec It’s… ou The… is… puis une indication de lieu.", 'example': "Where is the key? It’s on the table. = Où est la clé ? Elle est sur la table.", 'french': "Où est la clé ? Elle est sur la table.", 'question': "Quelle question demande où se trouve une clé ?", 'options': <String>["Where is the key?", "What is the key?", "Who is the key?"], 'answer': 0, 'correction': "Where demande un lieu.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L23", 'level': 'A1', 'title': "Répondre It’s on…", 'subtitle': "Sous-chapitre 6 • Leçon 23/50", 'explanation': "It’s on… signifie il/elle est sur… ; on est suivi de la surface ou du support.", 'example': "It’s on the desk. = C’est sur le bureau.", 'french': "C’est sur le bureau.", 'question': "Complète : It’s ___ the table.", 'options': <String>["on", "are", "does"], 'answer': 0, 'correction': "On indique la position sur une surface.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L24", 'level': 'A1', 'title': "Street et road", 'subtitle': "Sous-chapitre 6 • Leçon 24/50", 'explanation': "Street signifie rue ; road signifie route ou voie. Les deux se recoupent, mais street est fréquent pour une rue en ville.", 'example': "My school is on this street. = Mon école est dans cette rue.", 'french': "Mon école est dans cette rue.", 'question': "Street signifie…", 'options': <String>["Rue", "Maison", "Ville"], 'answer': 0, 'correction': "Street signifie rue.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L25", 'level': 'A1', 'title': "Neighborhood et city", 'subtitle': "Sous-chapitre 6 • Leçon 25/50", 'explanation': "Neighborhood signifie quartier ; city signifie ville. Neighborhood est souvent utilisé pour parler de la zone autour de son logement.", 'example': "My neighborhood is quiet. = Mon quartier est calme.", 'french': "Mon quartier est calme.", 'question': "Neighborhood signifie…", 'options': <String>["Quartier", "Pays", "Continent"], 'answer': 0, 'correction': "Neighborhood désigne un quartier.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L26", 'level': 'A1', 'title': "Village et country", 'subtitle': "Sous-chapitre 6 • Leçon 26/50", 'explanation': "Village signifie village ; country signifie pays, mais peut aussi signifier campagne dans certains contextes. La phrase aide à choisir le sens.", 'example': "I live in a village. = J’habite dans un village.", 'french': "J’habite dans un village.", 'question': "Village signifie…", 'options': <String>["Village", "Pays", "Rue"], 'answer': 0, 'correction': "Village signifie village.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L27", 'level': 'A1', 'title': "School et library", 'subtitle': "Sous-chapitre 6 • Leçon 27/50", 'explanation': "School signifie école ; library signifie bibliothèque. Une library est un lieu où l’on peut lire ou emprunter des livres.", 'example': "The library is near the school. = La bibliothèque est près de l’école.", 'french': "La bibliothèque est près de l’école.", 'question': "Library signifie…", 'options': <String>["Librairie", "Bibliothèque", "Laboratoire"], 'answer': 1, 'correction': "Library signifie bibliothèque ; bookstore signifie librairie.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L28", 'level': 'A1', 'title': "Hospital et pharmacy", 'subtitle': "Sous-chapitre 6 • Leçon 28/50", 'explanation': "Hospital signifie hôpital ; pharmacy signifie pharmacie. Ces lieux sont utiles pour demander un renseignement en ville.", 'example': "The pharmacy is near the hospital. = La pharmacie est près de l’hôpital.", 'french': "La pharmacie est près de l’hôpital.", 'question': "Pharmacy signifie…", 'options': <String>["Pharmacie", "Hôpital", "École"], 'answer': 0, 'correction': "Pharmacy signifie pharmacie.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L29", 'level': 'A1', 'title': "Market et supermarket", 'subtitle': "Sous-chapitre 6 • Leçon 29/50", 'explanation': "Market signifie marché ; supermarket signifie supermarché. Les deux sont des lieux où l’on achète des produits.", 'example': "I buy fruit at the market. = J’achète des fruits au marché.", 'french': "J’achète des fruits au marché.", 'question': "Supermarket signifie…", 'options': <String>["Supermarché", "Bibliothèque", "Arrêt de bus"], 'answer': 0, 'correction': "Supermarket désigne un grand magasin alimentaire.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L30", 'level': 'A1', 'title': "Bank et post office", 'subtitle': "Sous-chapitre 6 • Leçon 30/50", 'explanation': "Bank signifie banque ; post office signifie bureau de poste. On peut demander leur emplacement avec Where is…?", 'example': "The bank is across from the post office. = La banque est en face du bureau de poste.", 'french': "La banque est en face du bureau de poste.", 'question': "Post office signifie…", 'options': <String>["Bureau de poste", "Hôpital", "Gare"], 'answer': 0, 'correction': "Post office est le bureau de poste.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L31", 'level': 'A1', 'title': "Park et playground", 'subtitle': "Sous-chapitre 6 • Leçon 31/50", 'explanation': "Park signifie parc ; playground signifie aire de jeux. Ces lieux peuvent apparaître dans une description de quartier.", 'example': "The children are at the playground. = Les enfants sont à l’aire de jeux.", 'french': "Les enfants sont à l’aire de jeux.", 'question': "Playground signifie…", 'options': <String>["Aire de jeux", "Salle de classe", "Parking"], 'answer': 0, 'correction': "Playground est un espace de jeu.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L32", 'level': 'A1', 'title': "Restaurant et café", 'subtitle': "Sous-chapitre 6 • Leçon 32/50", 'explanation': "Restaurant signifie restaurant ; café peut désigner un café ou un petit établissement où l’on prend une boisson ou un repas léger.", 'example': "The café is next to the restaurant. = Le café est à côté du restaurant.", 'french': "Le café est à côté du restaurant.", 'question': "Restaurant signifie…", 'options': <String>["Restaurant", "Magasin", "Gare"], 'answer': 0, 'correction': "Restaurant a le même sens en anglais.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L33", 'level': 'A1', 'title': "Bus stop et train station", 'subtitle': "Sous-chapitre 6 • Leçon 33/50", 'explanation': "Bus stop signifie arrêt de bus ; train station signifie gare ferroviaire. Pour demander l’emplacement, utilise Where is the…?", 'example': "Where is the bus stop? = Où est l’arrêt de bus ?", 'french': "Où est l’arrêt de bus ?", 'question': "Bus stop signifie…", 'options': <String>["Arrêt de bus", "Gare", "Aéroport"], 'answer': 0, 'correction': "Bus stop est le lieu où le bus s’arrête.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L34", 'level': 'A1', 'title': "Demander Where is the bank?", 'subtitle': "Sous-chapitre 6 • Leçon 34/50", 'explanation': "Pour demander une direction, commence poliment par Excuse me, puis Where is the bank?", 'example': "Excuse me, where is the bank? = Excusez-moi, où est la banque ?", 'french': "Excusez-moi, où est la banque ?", 'question': "Quelle formule rend la demande polie ?", 'options': <String>["Excuse me", "Go away", "Never mind"], 'answer': 0, 'correction': "Excuse me attire poliment l’attention.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L35", 'level': 'A1', 'title': "Comprendre Go straight", 'subtitle': "Sous-chapitre 6 • Leçon 35/50", 'explanation': "Go straight signifie allez tout droit. C’est une instruction fréquente pour donner un itinéraire.", 'example': "Go straight for two blocks. = Allez tout droit pendant deux pâtés de maisons.", 'french': "Allez tout droit pendant deux pâtés de maisons.", 'question': "Go straight signifie…", 'options': <String>["Tournez à gauche", "Allez tout droit", "Arrêtez-vous"], 'answer': 1, 'correction': "Straight signifie tout droit.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L36", 'level': 'A1', 'title': "Comprendre Turn left", 'subtitle': "Sous-chapitre 6 • Leçon 36/50", 'explanation': "Turn left signifie tournez à gauche. Turn est le verbe tourner ; left signifie gauche.", 'example': "Turn left at the corner. = Tournez à gauche au coin.", 'french': "Tournez à gauche au coin.", 'question': "Turn left signifie…", 'options': <String>["Tournez à droite", "Tournez à gauche", "Continuez tout droit"], 'answer': 1, 'correction': "Left signifie gauche.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L37", 'level': 'A1', 'title': "Comprendre Turn right", 'subtitle': "Sous-chapitre 6 • Leçon 37/50", 'explanation': "Turn right signifie tournez à droite. Right peut aussi signifier correct ou droit selon le contexte.", 'example': "Turn right after the bank. = Tournez à droite après la banque.", 'french': "Tournez à droite après la banque.", 'question': "Right signifie dans Turn right…", 'options': <String>["Gauche", "Droite", "Derrière"], 'answer': 1, 'correction': "Dans cette instruction, right signifie droite.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L38", 'level': 'A1', 'title': "At the corner", 'subtitle': "Sous-chapitre 6 • Leçon 38/50", 'explanation': "At the corner signifie au coin, souvent au coin d’une rue. Cette expression aide à donner un itinéraire.", 'example': "The store is at the corner. = Le magasin est au coin.", 'french': "Le magasin est au coin.", 'question': "At the corner signifie…", 'options': <String>["Au coin", "Au sous-sol", "Au milieu de la maison"], 'answer': 0, 'correction': "Corner signifie coin.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L39", 'level': 'A1', 'title': "Across from et opposite", 'subtitle': "Sous-chapitre 6 • Leçon 39/50", 'explanation': "Across from et opposite peuvent signifier en face de. Across from est très courant en anglais américain pour localiser un lieu de l’autre côté.", 'example': "The bank is across from the park. = La banque est en face du parc.", 'french': "La banque est en face du parc.", 'question': "Across from signifie…", 'options': <String>["En face de", "Derrière", "À l’intérieur"], 'answer': 0, 'correction': "Across from indique une position en face.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L40", 'level': 'A1', 'title': "Near et far from", 'subtitle': "Sous-chapitre 6 • Leçon 40/50", 'explanation': "Near signifie près de ; far from signifie loin de. Ces expressions indiquent la distance approximative entre deux lieux.", 'example': "The school is near my house. = L’école est près de chez moi.", 'french': "L’école est près de chez moi.", 'question': "Far from signifie…", 'options': <String>["Près de", "Loin de", "À côté de"], 'answer': 1, 'correction': "Far from indique une grande distance.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L41", 'level': 'A1', 'title': "Question Is it far?", 'subtitle': "Sous-chapitre 6 • Leçon 41/50", 'explanation': "Is it far? signifie « Est-ce loin ? ». C’est une question pratique lorsqu’on demande son chemin.", 'example': "Is it far from here? = Est-ce loin d’ici ?", 'french': "Est-ce loin d’ici ?", 'question': "Quelle question demande si un lieu est loin ?", 'options': <String>["Is it far?", "Is it near school?", "What far?"], 'answer': 0, 'correction': "Far signifie loin.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L42", 'level': 'A1', 'title': "Question How can I get to…?", 'subtitle': "Sous-chapitre 6 • Leçon 42/50", 'explanation': "How can I get to the station? demande comment se rendre à la gare. Cette formule est polie et naturelle.", 'example': "How can I get to the hospital? = Comment puis-je aller à l’hôpital ?", 'french': "Comment puis-je aller à l’hôpital ?", 'question': "Quelle question demande un itinéraire ?", 'options': <String>["How can I get to…?", "How old is…?", "How much is…?"], 'answer': 0, 'correction': "Get to signifie arriver à ou se rendre à dans cette question.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L43", 'level': 'A1', 'title': "Comprendre un itinéraire en deux étapes", 'subtitle': "Sous-chapitre 6 • Leçon 43/50", 'explanation': "Un itinéraire peut contenir plusieurs consignes : go straight, then turn left. Écoute l’ordre des actions pour suivre le trajet.", 'example': "Go straight, then turn right. = Allez tout droit, puis tournez à droite.", 'french': "Allez tout droit, puis tournez à droite.", 'question': "Quel mot indique l’étape suivante ?", 'options': <String>["then", "blue", "because"], 'answer': 0, 'correction': "Then signifie ensuite.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L44", 'level': 'A1', 'title': "Bus et taxi", 'subtitle': "Sous-chapitre 6 • Leçon 44/50", 'explanation': "Bus signifie autobus ; taxi signifie taxi. Pour parler du moyen de transport, on dit take the bus ou take a taxi.", 'example': "I take the bus to school. = Je prends le bus pour aller à l’école.", 'french': "Je prends le bus pour aller à l’école.", 'question': "Comment dire « prendre le bus » ?", 'options': <String>["take the bus", "do the bus", "make bus"], 'answer': 0, 'correction': "Take the bus est l’expression naturelle.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L45", 'level': 'A1', 'title': "Car, bicycle et motorcycle", 'subtitle': "Sous-chapitre 6 • Leçon 45/50", 'explanation': "Car signifie voiture ; bicycle ou bike signifie vélo ; motorcycle signifie moto. Bike est très courant à l’oral pour bicycle.", 'example': "I ride a bicycle. = Je fais du vélo.", 'french': "Je fais du vélo.", 'question': "Motorcycle signifie…", 'options': <String>["Voiture", "Moto", "Autobus"], 'answer': 1, 'correction': "Motorcycle signifie moto.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L46", 'level': 'A1', 'title': "By bus et on foot", 'subtitle': "Sous-chapitre 6 • Leçon 46/50", 'explanation': "Pour indiquer un moyen de transport, on utilise by bus, by car, by train. L’expression est on foot pour « à pied ».", 'example': "I go to school by bus. = Je vais à l’école en bus. / I walk on foot. = J’y vais à pied.", 'french': "J’y vais à pied.", 'question': "Comment dire « en bus » ?", 'options': <String>["by bus", "on bus", "with bus"], 'answer': 0, 'correction': "By précède le moyen de transport ; on foot est une exception courante.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L47", 'level': 'A1', 'title': "Question Which bus goes to…?", 'subtitle': "Sous-chapitre 6 • Leçon 47/50", 'explanation': "Which bus goes to…? demande quel bus va à un endroit. Which signifie lequel ou quel parmi un choix.", 'example': "Which bus goes to the market? = Quel bus va au marché ?", 'french': "Quel bus va au marché ?", 'question': "Which bus goes to… demande…", 'options': <String>["Quel bus va à…", "Combien coûte le bus", "Où est le chauffeur"], 'answer': 0, 'correction': "Which sert à choisir parmi plusieurs options.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L48", 'level': 'A1', 'title': "Comprendre une adresse simple", 'subtitle': "Sous-chapitre 6 • Leçon 48/50", 'explanation': "Une adresse peut contenir un numéro, un nom de rue, une ville et un pays. Lis les éléments dans l’ordre et épelle les noms difficiles si nécessaire.", 'example': "12 Main Street, Dallas. = 12, rue Main, Dallas.", 'french': "12, rue Main, Dallas.", 'question': "Quel élément peut apparaître dans une adresse ?", 'options': <String>["Street", "Breakfast", "Happy"], 'answer': 0, 'correction': "Street est un élément fréquent dans une adresse anglophone.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L49", 'level': 'A1', 'title': "Lire une carte de quartier", 'subtitle': "Sous-chapitre 6 • Leçon 49/50", 'explanation': "Sur une carte, repère les symboles et les noms de lieux. Utilise near, next to, across from et between pour expliquer les positions.", 'example': "The school is next to the park. = L’école est à côté du parc.", 'french': "L’école est à côté du parc.", 'question': "Next to signifie…", 'options': <String>["À côté de", "Au-dessus de", "Loin de"], 'answer': 0, 'correction': "Next to décrit deux lieux voisins.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L50", 'level': 'A1', 'title': "Révision : suivre un itinéraire", 'subtitle': "Sous-chapitre 6 • Leçon 50/50", 'explanation': "Réutilise les lieux, les prépositions et les consignes de direction pour demander puis suivre un itinéraire simple.", 'example': "Excuse me, where is the library? Go straight and turn left. = Excusez-moi, où est la bibliothèque ? Allez tout droit et tournez à gauche.", 'french': "Excusez-moi, où est la bibliothèque ? Allez tout droit et tournez à gauche.", 'question': "Turn left signifie…", 'options': <String>["Tournez à droite", "Tournez à gauche", "Allez tout droit"], 'answer': 1, 'correction': "Left signifie gauche.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L01", 'level': 'A1', 'title': "Water et juice", 'subtitle': "Sous-chapitre 7 • Leçon 1/50", 'explanation': "Water signifie eau ; juice signifie jus. Pour commander, on peut dire water, please ou orange juice, please.", 'example': "Can I have water, please? = Puis-je avoir de l’eau, s’il vous plaît ?", 'french': "Puis-je avoir de l’eau, s’il vous plaît ?", 'question': "Juice signifie…", 'options': <String>["Jus", "Soupe", "Pain"], 'answer': 0, 'correction': "Juice signifie jus.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L02", 'level': 'A1', 'title': "Tea et coffee", 'subtitle': "Sous-chapitre 7 • Leçon 2/50", 'explanation': "Tea signifie thé ; coffee signifie café. Pour commander, ajoute please pour être poli.", 'example': "I drink tea in the morning. = Je bois du thé le matin.", 'french': "Je bois du thé le matin.", 'question': "Coffee signifie…", 'options': <String>["Café", "Thé", "Lait"], 'answer': 0, 'correction': "Coffee signifie café.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L03", 'level': 'A1', 'title': "Milk et autres boissons", 'subtitle': "Sous-chapitre 7 • Leçon 3/50", 'explanation': "Milk signifie lait. D’autres boissons courantes sont soda, lemonade et hot chocolate. Les noms de boissons sont utiles au café et au magasin.", 'example': "I’d like a glass of milk. = Je voudrais un verre de lait.", 'french': "Je voudrais un verre de lait.", 'question': "Milk signifie…", 'options': <String>["Lait", "Jus", "Eau"], 'answer': 0, 'correction': "Milk signifie lait.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L04", 'level': 'A1', 'title': "Bread et rice", 'subtitle': "Sous-chapitre 7 • Leçon 4/50", 'explanation': "Bread signifie pain ; rice signifie riz. En anglais, bread et rice sont généralement indénombrables lorsqu’on parle des aliments en général.", 'example': "I eat bread and rice. = Je mange du pain et du riz.", 'french': "Je mange du pain et du riz.", 'question': "Rice signifie…", 'options': <String>["Riz", "Pain", "Pâtes"], 'answer': 0, 'correction': "Rice signifie riz.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L05", 'level': 'A1', 'title': "Pasta et potatoes", 'subtitle': "Sous-chapitre 7 • Leçon 5/50", 'explanation': "Pasta signifie pâtes ; potato signifie pomme de terre, potatoes au pluriel. Attention à l’orthographe du pluriel en -oes.", 'example': "We have pasta for dinner. = Nous mangeons des pâtes au dîner.", 'french': "Nous mangeons des pâtes au dîner.", 'question': "Potatoes signifie…", 'options': <String>["Pommes de terre", "Tomates", "Carottes"], 'answer': 0, 'correction': "Potatoes est le pluriel de potato.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L06", 'level': 'A1', 'title': "Chicken et fish", 'subtitle': "Sous-chapitre 7 • Leçon 6/50", 'explanation': "Chicken signifie poulet ; fish signifie poisson. Chicken peut désigner la viande ou l’animal selon le contexte.", 'example': "I like chicken and fish. = J’aime le poulet et le poisson.", 'french': "J’aime le poulet et le poisson.", 'question': "Fish signifie…", 'options': <String>["Poisson", "Poulet", "Œuf"], 'answer': 0, 'correction': "Fish signifie poisson.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L07", 'level': 'A1', 'title': "Meat et eggs", 'subtitle': "Sous-chapitre 7 • Leçon 7/50", 'explanation': "Meat signifie viande ; egg signifie œuf, eggs au pluriel. Utilise these foods dans une phrase de repas.", 'example': "I eat eggs for breakfast. = Je mange des œufs au petit-déjeuner.", 'french': "Je mange des œufs au petit-déjeuner.", 'question': "Eggs signifie…", 'options': <String>["Œufs", "Pain", "Fruits"], 'answer': 0, 'correction': "Eggs est le pluriel de egg.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L08", 'level': 'A1', 'title': "Beans et vegetables", 'subtitle': "Sous-chapitre 7 • Leçon 8/50", 'explanation': "Beans signifie haricots ; vegetables signifie légumes. Vegetable est le singulier, vegetables le pluriel courant.", 'example': "I eat vegetables every day. = Je mange des légumes chaque jour.", 'french': "Je mange des légumes chaque jour.", 'question': "Vegetables signifie…", 'options': <String>["Légumes", "Boissons", "Desserts"], 'answer': 0, 'correction': "Vegetables signifie légumes.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L09", 'level': 'A1', 'title': "Fruits courants", 'subtitle': "Sous-chapitre 7 • Leçon 9/50", 'explanation': "Fruit est le mot général pour fruit ; les noms courants incluent apple, banana, orange, mango et pineapple.", 'example': "I like mangoes. = J’aime les mangues.", 'french': "J’aime les mangues.", 'question': "Banana signifie…", 'options': <String>["Banane", "Pomme", "Orange"], 'answer': 0, 'correction': "Banana signifie banane.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L10", 'level': 'A1', 'title': "Apple, banana et orange", 'subtitle': "Sous-chapitre 7 • Leçon 10/50", 'explanation': "Apple signifie pomme ; banana banane ; orange orange. Utilise an devant apple et orange, mais a devant banana.", 'example': "an apple, a banana, an orange.", 'french': "an apple, a banana, an orange.", 'question': "Quelle expression est correcte ?", 'options': <String>["a apple", "an apple", "an banana"], 'answer': 1, 'correction': "Apple commence par un son voyelle, donc an.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L11", 'level': 'A1', 'title': "Breakfast foods", 'subtitle': "Sous-chapitre 7 • Leçon 11/50", 'explanation': "Breakfast foods incluent eggs, bread, cereal, fruit et oatmeal. On dit have breakfast pour prendre le petit-déjeuner.", 'example': "I have eggs for breakfast. = Je mange des œufs au petit-déjeuner.", 'french': "Je mange des œufs au petit-déjeuner.", 'question': "Breakfast signifie…", 'options': <String>["Petit-déjeuner", "Dîner", "Goûter"], 'answer': 0, 'correction': "Breakfast est le repas du matin.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L12", 'level': 'A1', 'title': "Lunch et dinner", 'subtitle': "Sous-chapitre 7 • Leçon 12/50", 'explanation': "Lunch signifie déjeuner ; dinner signifie dîner ou repas principal selon le contexte. On dit have lunch et have dinner.", 'example': "We have lunch at noon. = Nous déjeunons à midi.", 'french': "Nous déjeunons à midi.", 'question': "Lunch signifie…", 'options': <String>["Déjeuner", "Petit-déjeuner", "Dîner uniquement"], 'answer': 0, 'correction': "Lunch est le repas du milieu de journée.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L13", 'level': 'A1', 'title': "Snacks et dessert", 'subtitle': "Sous-chapitre 7 • Leçon 13/50", 'explanation': "Snack signifie collation ou petit encas ; dessert signifie dessert. Ces mots sont utiles pour parler des habitudes alimentaires.", 'example': "I eat a snack after school. = Je prends un encas après l’école.", 'french': "Je prends un encas après l’école.", 'question': "Dessert signifie…", 'options': <String>["Dessert", "Dîner", "Petit-déjeuner"], 'answer': 0, 'correction': "Dessert est le dernier plat sucré d’un repas.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L14", 'level': 'A1', 'title': "Hungry et thirsty", 'subtitle': "Sous-chapitre 7 • Leçon 14/50", 'explanation': "Hungry signifie avoir faim ; thirsty signifie avoir soif. On utilise be : I’m hungry, I’m thirsty.", 'example': "I’m thirsty. Can I have water? = J’ai soif. Puis-je avoir de l’eau ?", 'french': "J’ai soif. Puis-je avoir de l’eau ?", 'question': "Thirsty signifie…", 'options': <String>["Avoir faim", "Avoir soif", "Être fatigué"], 'answer': 1, 'correction': "Thirsty signifie avoir soif.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L15", 'level': 'A1', 'title': "Dire I’m hungry et I’m thirsty", 'subtitle': "Sous-chapitre 7 • Leçon 15/50", 'explanation': "Ces expressions décrivent un besoin physique. Utilise I’m + hungry/thirsty, puis demande poliment quelque chose à manger ou à boire.", 'example': "I’m hungry. I’d like a sandwich. = J’ai faim. Je voudrais un sandwich.", 'french': "J’ai faim. Je voudrais un sandwich.", 'question': "Quelle phrase signifie « J’ai faim » ?", 'options': <String>["I’m hungry.", "I have hungry.", "I hungry am."], 'answer': 0, 'correction': "Hungry est un adjectif ; utilise le verbe be.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L16", 'level': 'A1', 'title': "Exprimer ses goûts avec I like", 'subtitle': "Sous-chapitre 7 • Leçon 16/50", 'explanation': "I like + nom sert à exprimer un goût. Pour une activité, on peut dire I like + verbe en -ing.", 'example': "I like apples. = J’aime les pommes.", 'french': "J’aime les pommes.", 'question': "Comment dire « J’aime les pommes » ?", 'options': <String>["I like apples.", "I likes apples.", "I am like apples."], 'answer': 0, 'correction': "Avec I, on utilise like sans -s.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L17", 'level': 'A1', 'title': "Exprimer un dégoût avec I don’t like", 'subtitle': "Sous-chapitre 7 • Leçon 17/50", 'explanation': "I don’t like signifie je n’aime pas. Après don’t, le verbe reste à la base : don’t like, et non don’t likes.", 'example': "I don’t like coffee. = Je n’aime pas le café.", 'french': "Je n’aime pas le café.", 'question': "Complète : I don’t ___ fish.", 'options': <String>["likes", "like", "liking"], 'answer': 1, 'correction': "Après don’t, utilise la base verbale like.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L18", 'level': 'A1', 'title': "Question Do you like…?", 'subtitle': "Sous-chapitre 7 • Leçon 18/50", 'explanation': "Do you like…? demande si quelqu’un aime quelque chose. Réponds Yes, I do ou No, I don’t.", 'example': "Do you like tea? — Yes, I do. = Aimes-tu le thé ? — Oui.", 'french': "Aimes-tu le thé ? — Oui.", 'question': "Quelle question demande si quelqu’un aime le thé ?", 'options': <String>["Do you like tea?", "Are you like tea?", "Does you like tea?"], 'answer': 0, 'correction': "Avec you, on utilise do.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L19", 'level': 'A1', 'title': "Some dans une demande polie", 'subtitle': "Sous-chapitre 7 • Leçon 19/50", 'explanation': "Some signifie un peu de ou quelques. Il est fréquent dans les offres et demandes polies : some water, some bread.", 'example': "Can I have some water, please? = Puis-je avoir de l’eau, s’il vous plaît ?", 'french': "Puis-je avoir de l’eau, s’il vous plaît ?", 'question': "Some water signifie…", 'options': <String>["Un peu d’eau / de l’eau", "Toute l’eau du monde", "Une eau"], 'answer': 0, 'correction': "Some s’utilise naturellement dans cette demande.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L20", 'level': 'A1', 'title': "Noms dénombrables", 'subtitle': "Sous-chapitre 7 • Leçon 20/50", 'explanation': "Un nom dénombrable peut être compté : one apple, two apples. Il a un singulier et un pluriel.", 'example': "three eggs = trois œufs.", 'french': "trois œufs.", 'question': "Lequel est dénombrable ?", 'options': <String>["apple", "water", "rice"], 'answer': 0, 'correction': "On peut compter les pommes une par une.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L21", 'level': 'A1', 'title': "Noms indénombrables courants", 'subtitle': "Sous-chapitre 7 • Leçon 21/50", 'explanation': "Certains noms sont généralement indénombrables : water, rice, bread, milk. On ne dit pas normalement one water pour parler de l’aliment en général.", 'example': "some water = de l’eau ; a glass of water = un verre d’eau.", 'french': "de l’eau ; a glass of water = un verre d’eau.", 'question': "Lequel est généralement indénombrable ?", 'options': <String>["apple", "water", "egg"], 'answer': 1, 'correction': "Water est généralement indénombrable.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L22", 'level': 'A1', 'title': "A piece of", 'subtitle': "Sous-chapitre 7 • Leçon 22/50", 'explanation': "A piece of signifie un morceau de. Cette expression permet de compter certains noms indénombrables comme bread ou cake.", 'example': "a piece of cake = un morceau de gâteau.", 'french': "un morceau de gâteau.", 'question': "Comment dire « un morceau de gâteau » ?", 'options': <String>["a cake of piece", "a piece of cake", "a piece cake"], 'answer': 1, 'correction': "La structure est a piece of + nom.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L23", 'level': 'A1', 'title': "A glass of et a cup of", 'subtitle': "Sous-chapitre 7 • Leçon 23/50", 'explanation': "A glass of s’utilise pour un verre de ; a cup of pour une tasse de. Le récipient permet de quantifier une boisson.", 'example': "a glass of water = un verre d’eau ; a cup of tea = une tasse de thé.", 'french': "un verre d’eau ; a cup of tea = une tasse de thé.", 'question': "Une tasse de thé se dit…", 'options': <String>["a glass tea", "a cup of tea", "a cup tea"], 'answer': 1, 'correction': "Cup signifie tasse et of relie la quantité à la boisson.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L24", 'level': 'A1', 'title': "A bottle of", 'subtitle': "Sous-chapitre 7 • Leçon 24/50", 'explanation': "A bottle of signifie une bouteille de. On peut dire a bottle of water ou a bottle of juice.", 'example': "I need a bottle of water. = J’ai besoin d’une bouteille d’eau.", 'french': "J’ai besoin d’une bouteille d’eau.", 'question': "Comment dire « une bouteille d’eau » ?", 'options': <String>["a bottle water", "a bottle of water", "a water bottle of"], 'answer': 1, 'correction': "La structure est a bottle of + contenu.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L25", 'level': 'A1', 'title': "Question How much…?", 'subtitle': "Sous-chapitre 7 • Leçon 25/50", 'explanation': "How much sert à demander la quantité d’un nom indénombrable ou le prix. Le contexte indique le sens.", 'example': "How much water do you drink? = Quelle quantité d’eau bois-tu ?", 'french': "Quelle quantité d’eau bois-tu ?", 'question': "How much peut demander…", 'options': <String>["Une quantité indénombrable", "Le pluriel d’un nom dénombrable uniquement", "Un jour de la semaine"], 'answer': 0, 'correction': "How much s’utilise avec des noms indénombrables et pour les prix.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L26", 'level': 'A1', 'title': "Question How many…?", 'subtitle': "Sous-chapitre 7 • Leçon 26/50", 'explanation': "How many sert à demander le nombre d’éléments dénombrables au pluriel.", 'example': "How many apples do you want? = Combien de pommes veux-tu ?", 'french': "Combien de pommes veux-tu ?", 'question': "Quelle question est correcte ?", 'options': <String>["How many apples?", "How much apples?", "How many water?"], 'answer': 0, 'correction': "Apples est dénombrable et pluriel, donc how many.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L27", 'level': 'A1', 'title': "Lire un prix simple", 'subtitle': "Sous-chapitre 7 • Leçon 27/50", 'explanation': "Pour lire un prix, repère la devise et les nombres. En dollars américains, \$4.50 se lit four dollars and fifty cents ou four fifty dans un contexte informel.", 'example': "It’s four dollars. = Cela coûte quatre dollars.", 'french': "Cela coûte quatre dollars.", 'question': "\$4.50 signifie…", 'options': <String>["Quatre dollars et cinquante cents", "Quarante-cinq dollars", "Quatre cents"], 'answer': 0, 'correction': "Le point sépare les dollars des cents dans cette notation.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L28", 'level': 'A1', 'title': "Dollars et cents dans les prix", 'subtitle': "Sous-chapitre 7 • Leçon 28/50", 'explanation': "Dollar est l’unité monétaire ; cent est un centième de dollar. Un prix de \$1.25 vaut un dollar et vingt-cinq cents.", 'example': "It costs one dollar and twenty-five cents. = Cela coûte un dollar vingt-cinq.", 'french': "Cela coûte un dollar vingt-cinq.", 'question': "25 cents est…", 'options': <String>["Un quart de dollar", "25 dollars", "Deux dollars"], 'answer': 0, 'correction': "Cent représente un centième de dollar.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L29", 'level': 'A1', 'title': "Question How much is it?", 'subtitle': "Sous-chapitre 7 • Leçon 29/50", 'explanation': "How much is it? demande combien coûte un article. On répond It’s five dollars ou It costs five dollars.", 'example': "How much is it? — It’s five dollars. = Combien ça coûte ? — Cinq dollars.", 'french': "Combien ça coûte ? — Cinq dollars.", 'question': "Quelle question demande le prix ?", 'options': <String>["How much is it?", "How old is it?", "How many is it?"], 'answer': 0, 'correction': "How much is it est une question de prix courante.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L30", 'level': 'A1', 'title': "Question How much are these?", 'subtitle': "Sous-chapitre 7 • Leçon 30/50", 'explanation': "Pour demander le prix de plusieurs objets, on peut dire How much are these? These est pluriel, donc le verbe est are.", 'example': "How much are these apples? = Combien coûtent ces pommes ?", 'french': "Combien coûtent ces pommes ?", 'question': "Quelle forme convient pour plusieurs objets ?", 'options': <String>["How much is these?", "How much are these?", "How many are this?"], 'answer': 1, 'correction': "These est pluriel et prend are.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L31", 'level': 'A1', 'title': "Cheap et expensive", 'subtitle': "Sous-chapitre 7 • Leçon 31/50", 'explanation': "Cheap signifie bon marché ; expensive signifie cher. Ces adjectifs servent à comparer les prix.", 'example': "This phone is expensive. = Ce téléphone est cher.", 'french': "Ce téléphone est cher.", 'question': "Cheap signifie…", 'options': <String>["Cher", "Bon marché", "Gratuit"], 'answer': 1, 'correction': "Cheap signifie bon marché, pas nécessairement gratuit.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L32", 'level': 'A1', 'title': "Demander le prix poliment", 'subtitle': "Sous-chapitre 7 • Leçon 32/50", 'explanation': "Pour demander le prix, utilise How much is this? ou How much does it cost? Ajoute Excuse me pour attirer poliment l’attention.", 'example': "Excuse me, how much is this? = Excusez-moi, combien coûte ceci ?", 'french': "Excusez-moi, combien coûte ceci ?", 'question': "Quelle expression est une demande polie de prix ?", 'options': <String>["How much is this?", "Give me price!", "Price where?"], 'answer': 0, 'correction': "La structure est naturelle et polie.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L33", 'level': 'A1', 'title': "I’d like…", 'subtitle': "Sous-chapitre 7 • Leçon 33/50", 'explanation': "I’d like est la contraction de I would like et signifie je voudrais. C’est une formule polie pour commander ou demander quelque chose.", 'example': "I’d like a sandwich, please. = Je voudrais un sandwich, s’il vous plaît.", 'french': "Je voudrais un sandwich, s’il vous plaît.", 'question': "I’d like signifie…", 'options': <String>["Je voudrais", "J’ai aimé hier", "Je dois"], 'answer': 0, 'correction': "I’d like est plus poli que I want dans de nombreuses commandes.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L34", 'level': 'A1', 'title': "Can I have…?", 'subtitle': "Sous-chapitre 7 • Leçon 34/50", 'explanation': "Can I have…? signifie puis-je avoir…? C’est une formule courante pour demander un objet, une boisson ou un service.", 'example': "Can I have the menu, please? = Puis-je avoir le menu, s’il vous plaît ?", 'french': "Puis-je avoir le menu, s’il vous plaît ?", 'question': "Quelle formule demande poliment un menu ?", 'options': <String>["Can I have the menu, please?", "I menu have.", "Give menu now."], 'answer': 0, 'correction': "Can I have est une demande polie courante.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L35", 'level': 'A1', 'title': "Commander une boisson", 'subtitle': "Sous-chapitre 7 • Leçon 35/50", 'explanation': "Pour commander, dis I’d like a coffee, please ou Can I have some water? Écoute aussi les questions du serveur.", 'example': "I’d like an orange juice, please. = Je voudrais un jus d’orange, s’il vous plaît.", 'french': "Je voudrais un jus d’orange, s’il vous plaît.", 'question': "Quelle phrase commande poliment un café ?", 'options': <String>["I’d like a coffee, please.", "I coffee want now.", "Coffee me."], 'answer': 0, 'correction': "I’d like + article + boisson est une structure naturelle.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L36", 'level': 'A1', 'title': "Commander un repas simple", 'subtitle': "Sous-chapitre 7 • Leçon 36/50", 'explanation': "Au restaurant, utilise I’d like… ou Can I have…? pour commander un plat. Ajoute please et thank you.", 'example': "I’d like the chicken, please. = Je voudrais le poulet, s’il vous plaît.", 'french': "Je voudrais le poulet, s’il vous plaît.", 'question': "Quelle phrase commande un plat poliment ?", 'options': <String>["I’d like the chicken, please.", "I chicken want.", "Give chicken!"], 'answer': 0, 'correction': "I’d like est une demande polie.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L37", 'level': 'A1', 'title': "Demander the menu", 'subtitle': "Sous-chapitre 7 • Leçon 37/50", 'explanation': "The menu signifie le menu. Pour le demander, dis Could I see the menu, please? ou Can I have the menu, please?", 'example': "Could I see the menu, please? = Pourrais-je voir le menu, s’il vous plaît ?", 'french': "Pourrais-je voir le menu, s’il vous plaît ?", 'question': "Menu signifie…", 'options': <String>["Menu", "Facture", "Cuisine"], 'answer': 0, 'correction': "Menu a le même sens en anglais.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L38", 'level': 'A1', 'title': "Demander the bill", 'subtitle': "Sous-chapitre 7 • Leçon 38/50", 'explanation': "The bill signifie l’addition dans un restaurant ; aux États-Unis, check est aussi très courant.", 'example': "Could we have the check, please? = Pourrions-nous avoir l’addition, s’il vous plaît ?", 'french': "Pourrions-nous avoir l’addition, s’il vous plaît ?", 'question': "Dans un restaurant américain, check peut signifier…", 'options': <String>["Addition", "Menu", "Cuisine"], 'answer': 0, 'correction': "Check est un mot américain courant pour l’addition.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L39", 'level': 'A1', 'title': "For here or to go?", 'subtitle': "Sous-chapitre 7 • Leçon 39/50", 'explanation': "Cette question signifie « sur place ou à emporter ? ». For here veut dire sur place ; to go signifie à emporter.", 'example': "For here, please. = Sur place, s’il vous plaît.", 'french': "Sur place, s’il vous plaît.", 'question': "To go signifie…", 'options': <String>["Sur place", "À emporter", "À payer"], 'answer': 1, 'correction': "Dans une commande, to go signifie à emporter.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L40", 'level': 'A1', 'title': "Comprendre Here you go", 'subtitle': "Sous-chapitre 7 • Leçon 40/50", 'explanation': "Here you go est une formule utilisée lorsqu’on remet quelque chose à quelqu’un, comme une boisson ou un ticket. Elle signifie approximativement « voilà ».", 'example': "Here you go. = Voilà.", 'french': "Voilà.", 'question': "Que peut dire le serveur en te donnant ta boisson ?", 'options': <String>["Here you go.", "Where you go?", "Go here now."], 'answer': 0, 'correction': "C’est une formule naturelle pour remettre un objet.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L41", 'level': 'A1', 'title': "Anything else? et réponse", 'subtitle': "Sous-chapitre 7 • Leçon 41/50", 'explanation': "Anything else? signifie « autre chose ? ». On peut répondre No, that’s all, thank you ou Yes, please.", 'example': "Anything else? — No, that’s all, thanks. = Autre chose ? — Non, ce sera tout, merci.", 'french': "Autre chose ? — Non, ce sera tout, merci.", 'question': "Que signifie Anything else?", 'options': <String>["Autre chose ?", "Où est-ce ?", "Combien ça coûte ?"], 'answer': 0, 'correction': "Else signifie autre dans cette question.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L42", 'level': 'A1', 'title': "Demander un plat sans ingrédient", 'subtitle': "Sous-chapitre 7 • Leçon 42/50", 'explanation': "Pour signaler une préférence, dis Can I have this without onions? Pour une allergie, sois clair : I’m allergic to peanuts.", 'example': "Can I have it without onions? = Puis-je l’avoir sans oignons ?", 'french': "Puis-je l’avoir sans oignons ?", 'question': "Without signifie…", 'options': <String>["Avec", "Sans", "Avant"], 'answer': 1, 'correction': "Without indique l’absence d’un ingrédient.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L43", 'level': 'A1', 'title': "Dire I’m allergic to…", 'subtitle': "Sous-chapitre 7 • Leçon 43/50", 'explanation': "I’m allergic to… signifie « Je suis allergique à… ». Cette phrase est importante pour communiquer un risque alimentaire ; indique l’ingrédient précisément.", 'example': "I’m allergic to peanuts. = Je suis allergique aux arachides.", 'french': "Je suis allergique aux arachides.", 'question': "Comment dire « Je suis allergique au lait » ?", 'options': <String>["I’m allergic to milk.", "I allergic milk.", "I’m allergy milk."], 'answer': 0, 'correction': "La structure est I’m allergic to + ingrédient.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L44", 'level': 'A1', 'title': "Store et shop", 'subtitle': "Sous-chapitre 7 • Leçon 44/50", 'explanation': "Store signifie magasin en anglais américain ; shop est aussi courant, notamment pour un type de commerce ou en anglais britannique.", 'example': "I’m going to the store. = Je vais au magasin.", 'french': "Je vais au magasin.", 'question': "Store signifie…", 'options': <String>["Magasin", "École", "Parc"], 'answer': 0, 'correction': "Store est très courant en anglais américain.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L45", 'level': 'A1', 'title': "Lire une liste de courses", 'subtitle': "Sous-chapitre 7 • Leçon 45/50", 'explanation': "Une shopping list contient des produits à acheter. Repère les quantités et les noms d’aliments ; coche chaque article acheté.", 'example': "We need milk, bread and eggs. = Nous avons besoin de lait, de pain et d’œufs.", 'french': "Nous avons besoin de lait, de pain et d’œufs.", 'question': "Shopping list signifie…", 'options': <String>["Liste de courses", "Carte scolaire", "Menu de restaurant"], 'answer': 0, 'correction': "Shopping list est une liste de produits à acheter.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L46", 'level': 'A1', 'title': "Question Where can I find…?", 'subtitle': "Sous-chapitre 7 • Leçon 46/50", 'explanation': "Where can I find…? signifie « Où puis-je trouver… ? ». C’est utile dans un magasin pour demander un produit.", 'example': "Where can I find the rice? = Où puis-je trouver le riz ?", 'french': "Où puis-je trouver le riz ?", 'question': "Quelle question demande où trouver un produit ?", 'options': <String>["Where can I find…?", "How much am I?", "When do I find?"], 'answer': 0, 'correction': "Where demande un lieu ; can I find signifie puis-je trouver.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L47", 'level': 'A1', 'title': "Buy, pay et cost", 'subtitle': "Sous-chapitre 7 • Leçon 47/50", 'explanation': "Buy signifie acheter ; pay signifie payer ; cost signifie coûter. Le passé de buy est bought et celui de pay est paid.", 'example': "I buy fruit. It costs two dollars. I pay cash. = J’achète des fruits. Cela coûte deux dollars. Je paie en espèces.", 'french': "J’achète des fruits. Cela coûte deux dollars. Je paie en espèces.", 'question': "Cost signifie…", 'options': <String>["Acheter", "Payer", "Coûter"], 'answer': 2, 'correction': "Cost signifie coûter.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L48", 'level': 'A1', 'title': "Receipt et change", 'subtitle': "Sous-chapitre 7 • Leçon 48/50", 'explanation': "Receipt signifie reçu ou ticket de caisse ; change signifie monnaie rendue après un paiement, ou changement selon le contexte.", 'example': "Can I have the receipt? = Puis-je avoir le reçu ?", 'french': "Puis-je avoir le reçu ?", 'question': "Receipt signifie…", 'options': <String>["Reçu", "Prix", "Sac"], 'answer': 0, 'correction': "Receipt est le justificatif d’achat.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L49", 'level': 'A1', 'title': "Dialogue client-vendeur", 'subtitle': "Sous-chapitre 7 • Leçon 49/50", 'explanation': "Un dialogue d’achat peut contenir une salutation, une demande de prix, un choix, un paiement et un remerciement. Réutilise les expressions polies.", 'example': "How much is this? — It’s five dollars. — I’ll take it, please. = Combien ça coûte ? — Cinq dollars. — Je le prends, s’il vous plaît.", 'french': "Combien ça coûte ? — Cinq dollars. — Je le prends, s’il vous plaît.", 'question': "Quelle phrase signifie « Je le prends » ?", 'options': <String>["I’ll take it.", "I cost it.", "I pay it tomorrow always."], 'answer': 0, 'correction': "I’ll take it exprime une décision d’achat.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L50", 'level': 'A1', 'title': "Révision : acheter et payer", 'subtitle': "Sous-chapitre 7 • Leçon 50/50", 'explanation': "Réutilise les nombres, les prix, les demandes polies et les expressions de paiement dans une situation complète.", 'example': "Excuse me, how much is this? — It’s three dollars. — I’ll take it. Can I have the receipt, please?", 'french': "Excuse me, how much is this? — It’s three dollars. — I’ll take it. Can I have the receipt, please?", 'question': "Quelle phrase demande le reçu ?", 'options': <String>["Can I have the receipt, please?", "How old is the receipt?", "Where is my price?"], 'answer': 0, 'correction': "Cette structure est une demande polie.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L01", 'level': 'A1', 'title': "Classroom et objets de classe", 'subtitle': "Sous-chapitre 8 • Leçon 1/50", 'explanation': "Classroom signifie salle de classe. Les objets courants sont desk, chair, board, notebook, pencil et eraser.", 'example': "The classroom is big. = La salle de classe est grande.", 'french': "La salle de classe est grande.", 'question': "Classroom signifie…", 'options': <String>["Salle de classe", "Bureau", "Couloir"], 'answer': 0, 'correction': "Classroom est le lieu où les élèves suivent le cours.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L02", 'level': 'A1', 'title': "Teacher et student", 'subtitle': "Sous-chapitre 8 • Leçon 2/50", 'explanation': "Teacher signifie enseignant ou professeur ; student signifie élève ou étudiant selon le contexte.", 'example': "The teacher helps the students. = Le professeur aide les élèves.", 'french': "Le professeur aide les élèves.", 'question': "Student signifie…", 'options': <String>["Élève / étudiant", "Professeur", "Parent"], 'answer': 0, 'correction': "Student désigne une personne qui apprend.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L03", 'level': 'A1', 'title': "Subject et lesson", 'subtitle': "Sous-chapitre 8 • Leçon 3/50", 'explanation': "Subject signifie matière scolaire ; lesson signifie leçon. Subject peut aussi avoir d’autres sens, mais à l’école il désigne une matière.", 'example': "English is my favorite subject. = L’anglais est ma matière préférée.", 'french': "L’anglais est ma matière préférée.", 'question': "Subject signifie à l’école…", 'options': <String>["Matière", "Récréation", "Chaise"], 'answer': 0, 'correction': "Subject désigne une matière scolaire dans cet exemple.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L04", 'level': 'A1', 'title': "English class", 'subtitle': "Sous-chapitre 8 • Leçon 4/50", 'explanation': "English class signifie cours d’anglais. On peut dire I have English class today ou My English class starts at nine.", 'example': "I have English class today. = J’ai cours d’anglais aujourd’hui.", 'french': "J’ai cours d’anglais aujourd’hui.", 'question': "English class signifie…", 'options': <String>["Cours d’anglais", "Livre d’anglais", "Professeur d’anglais uniquement"], 'answer': 0, 'correction': "Class peut signifier classe ou cours.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L05", 'level': 'A1', 'title': "Maths et science", 'subtitle': "Sous-chapitre 8 • Leçon 5/50", 'explanation': "Math signifie mathématiques en anglais américain ; maths est courant en anglais britannique. Science signifie sciences.", 'example': "I like science. = J’aime les sciences.", 'french': "J’aime les sciences.", 'question': "Science signifie…", 'options': <String>["Sciences", "Histoire", "Musique"], 'answer': 0, 'correction': "Science désigne les sciences comme matière.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L06", 'level': 'A1', 'title': "Utiliser have a class", 'subtitle': "Sous-chapitre 8 • Leçon 6/50", 'explanation': "Have a class signifie avoir un cours. Au présent, on utilise have avec I/you/we/they et has avec he/she/it.", 'example': "I have a class at ten. = J’ai un cours à dix heures.", 'french': "J’ai un cours à dix heures.", 'question': "She ___ a class today.", 'options': <String>["have", "has", "having"], 'answer': 1, 'correction': "Avec she au présent simple, on utilise has.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L07", 'level': 'A1', 'title': "Comprendre Open your book", 'subtitle': "Sous-chapitre 8 • Leçon 7/50", 'explanation': "Open your book est une consigne qui signifie « Ouvre ton livre ». L’impératif utilise la base verbale sans sujet exprimé.", 'example': "Open your book, please. = Ouvre ton livre, s’il te plaît.", 'french': "Ouvre ton livre, s’il te plaît.", 'question': "Que signifie Open your book?", 'options': <String>["Ferme ton livre", "Ouvre ton livre", "Lis ton livre"], 'answer': 1, 'correction': "Open signifie ouvrir.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L08", 'level': 'A1', 'title': "Comprendre Close your notebook", 'subtitle': "Sous-chapitre 8 • Leçon 8/50", 'explanation': "Close your notebook signifie « Ferme ton cahier ». Close est la base verbale à l’impératif.", 'example': "Close your notebook. = Ferme ton cahier.", 'french': "Ferme ton cahier.", 'question': "Close signifie…", 'options': <String>["Ouvrir", "Fermer", "Écrire"], 'answer': 1, 'correction': "Close signifie fermer.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L09", 'level': 'A1', 'title': "Comprendre Write your answer", 'subtitle': "Sous-chapitre 8 • Leçon 9/50", 'explanation': "Write your answer signifie « Écris ta réponse ». Write est la base verbale utilisée dans une consigne directe.", 'example': "Write your answer in English. = Écris ta réponse en anglais.", 'french': "Écris ta réponse en anglais.", 'question': "Write your answer signifie…", 'options': <String>["Lis ta réponse", "Écris ta réponse", "Écoute ta réponse"], 'answer': 1, 'correction': "Write signifie écrire.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L10", 'level': 'A1', 'title': "Comprendre Work in pairs", 'subtitle': "Sous-chapitre 8 • Leçon 10/50", 'explanation': "Work in pairs signifie « Travaillez par deux ». Pair signifie paire ou binôme ; in pairs indique la manière de travailler.", 'example': "Work in pairs, please. = Travaillez par deux, s’il vous plaît.", 'french': "Travaillez par deux, s’il vous plaît.", 'question': "Work in pairs signifie…", 'options': <String>["Travaillez seuls", "Travaillez par deux", "Travaillez dehors"], 'answer': 1, 'correction': "Pair signifie une paire de personnes.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L11", 'level': 'A1', 'title': "Demander Can you help me?", 'subtitle': "Sous-chapitre 8 • Leçon 11/50", 'explanation': "Can you help me? signifie « Peux-tu m’aider ? ». C’est une demande courante ; please peut la rendre plus polie.", 'example': "Can you help me, please? = Peux-tu m’aider, s’il te plaît ?", 'french': "Peux-tu m’aider, s’il te plaît ?", 'question': "Quelle phrase demande de l’aide ?", 'options': <String>["Can you help me?", "Can you hear me?", "Can you see me?"], 'answer': 0, 'correction': "Help signifie aider.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L12", 'level': 'A1', 'title': "Demander What page are we on?", 'subtitle': "Sous-chapitre 8 • Leçon 12/50", 'explanation': "What page are we on? demande à quelle page la classe est arrivée. Page signifie page ; on est utilisé dans cette expression.", 'example': "What page are we on? = Nous sommes à quelle page ?", 'french': "Nous sommes à quelle page ?", 'question': "Quelle question demande la page du livre ?", 'options': <String>["What page are we on?", "What book are you?", "Where page it?"], 'answer': 0, 'correction': "Cette expression est naturelle pour suivre une leçon.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L13", 'level': 'A1', 'title': "Dire I have a question", 'subtitle': "Sous-chapitre 8 • Leçon 13/50", 'explanation': "I have a question signifie « J’ai une question ». Have signifie avoir ; cette phrase permet d’intervenir en classe.", 'example': "Excuse me, I have a question. = Excusez-moi, j’ai une question.", 'french': "Excusez-moi, j’ai une question.", 'question': "Question signifie…", 'options': <String>["Question", "Réponse", "Leçon"], 'answer': 0, 'correction': "Question signifie question.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L14", 'level': 'A1', 'title': "Demander How do you spell it?", 'subtitle': "Sous-chapitre 8 • Leçon 14/50", 'explanation': "How do you spell it? demande comment épeler un mot. Spell signifie épeler ; it remplace le mot mentionné.", 'example': "How do you spell “friend”? = Comment épelle-t-on friend ?", 'french': "Comment épelle-t-on friend ?", 'question': "Spell signifie…", 'options': <String>["Épeler", "Prononcer", "Traduire"], 'answer': 0, 'correction': "Spell concerne les lettres du mot.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L15", 'level': 'A1', 'title': "Parler de homework", 'subtitle': "Sous-chapitre 8 • Leçon 15/50", 'explanation': "Homework signifie devoirs à faire à la maison. En anglais, homework est généralement indénombrable : on dit some homework, pas homeworks.", 'example': "I have homework tonight. = J’ai des devoirs ce soir.", 'french': "J’ai des devoirs ce soir.", 'question': "Homework signifie…", 'options': <String>["Devoirs à la maison", "Cours en classe", "Vacances"], 'answer': 0, 'correction': "Homework est généralement indénombrable.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L16", 'level': 'A1', 'title': "Test et exam", 'subtitle': "Sous-chapitre 8 • Leçon 16/50", 'explanation': "Test signifie test ou contrôle ; exam est une forme courte de examination, examen. Le contexte scolaire aide à comprendre le niveau de l’évaluation.", 'example': "I have an exam tomorrow. = J’ai un examen demain.", 'french': "J’ai un examen demain.", 'question': "Exam signifie…", 'options': <String>["Examen", "Exemple", "Explication"], 'answer': 0, 'correction': "Exam est une forme courte courante de examination.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L17", 'level': 'A1', 'title': "Pass et fail avec tact", 'subtitle': "Sous-chapitre 8 • Leçon 17/50", 'explanation': "Pass signifie réussir un examen ; fail signifie échouer. Ces mots décrivent un résultat, pas la valeur d’une personne.", 'example': "I passed the test. = J’ai réussi le test.", 'french': "J’ai réussi le test.", 'question': "Pass signifie dans un examen…", 'options': <String>["Réussir", "Oublier", "Réviser"], 'answer': 0, 'correction': "Passer/réussir un test se dit pass the test.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L18", 'level': 'A1', 'title': "Dire I’m ready", 'subtitle': "Sous-chapitre 8 • Leçon 18/50", 'explanation': "I’m ready signifie « Je suis prêt ». Ready est un adjectif qui suit le verbe be.", 'example': "I’m ready to start. = Je suis prêt à commencer.", 'french': "Je suis prêt à commencer.", 'question': "Ready signifie…", 'options': <String>["Prêt", "En retard", "Triste"], 'answer': 0, 'correction': "Ready décrit l’état d’être prêt.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L19", 'level': 'A1', 'title': "Dire I know et I don’t know", 'subtitle': "Sous-chapitre 8 • Leçon 19/50", 'explanation': "I know signifie je sais ; I don’t know signifie je ne sais pas. Ces expressions sont fréquentes dans les réponses.", 'example': "I don’t know the answer. = Je ne connais pas la réponse.", 'french': "Je ne connais pas la réponse.", 'question': "Comment dire « Je ne sais pas » ?", 'options': <String>["I no know.", "I don’t know.", "I doesn’t know."], 'answer': 1, 'correction': "La négation avec I utilise don’t + know.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L20", 'level': 'A1', 'title': "Parler de hobbies", 'subtitle': "Sous-chapitre 8 • Leçon 20/50", 'explanation': "Hobby signifie loisir ; hobbies est le pluriel. On peut dire My hobbies are music and football.", 'example': "My hobby is drawing. = Mon loisir est le dessin.", 'french': "Mon loisir est le dessin.", 'question': "Hobbies signifie…", 'options': <String>["Loisirs", "Devoirs", "Matières"], 'answer': 0, 'correction': "Hobbies est le pluriel de hobby.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L21", 'level': 'A1', 'title': "Music et singing", 'subtitle': "Sous-chapitre 8 • Leçon 21/50", 'explanation': "Music signifie musique ; singing signifie le chant ou le fait de chanter. On peut dire I like music ou I like singing.", 'example': "I love music. = J’adore la musique.", 'french': "J’adore la musique.", 'question': "Singing signifie…", 'options': <String>["Chanter / le chant", "Danser", "Lire"], 'answer': 0, 'correction': "Singing vient du verbe sing, chanter.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L22", 'level': 'A1', 'title': "Dancing et drawing", 'subtitle': "Sous-chapitre 8 • Leçon 22/50", 'explanation': "Dancing signifie danse ou le fait de danser ; drawing signifie dessin ou le fait de dessiner.", 'example': "I like dancing and drawing. = J’aime danser et dessiner.", 'french': "J’aime danser et dessiner.", 'question': "Drawing signifie…", 'options': <String>["Dessin / dessiner", "Courir", "Dormir"], 'answer': 0, 'correction': "Drawing est lié au verbe draw.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L23", 'level': 'A1', 'title': "Reading for fun", 'subtitle': "Sous-chapitre 8 • Leçon 23/50", 'explanation': "Reading for fun signifie lire pour le plaisir. For fun veut dire pour s’amuser ou par plaisir.", 'example': "I read comics for fun. = Je lis des bandes dessinées pour le plaisir.", 'french': "Je lis des bandes dessinées pour le plaisir.", 'question': "For fun signifie…", 'options': <String>["Pour le plaisir", "Pour l’école seulement", "En retard"], 'answer': 0, 'correction': "For fun décrit une activité faite par plaisir.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L24", 'level': 'A1', 'title': "Movies et TV shows", 'subtitle': "Sous-chapitre 8 • Leçon 24/50", 'explanation': "Movie signifie film ; TV show signifie émission ou série télévisée. Movie est le mot courant en anglais américain pour film.", 'example': "I watch movies on weekends. = Je regarde des films le week-end.", 'french': "Je regarde des films le week-end.", 'question': "Movie signifie…", 'options': <String>["Film", "Musique", "Journal"], 'answer': 0, 'correction': "Movie est le mot courant pour film.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L25", 'level': 'A1', 'title': "Video games", 'subtitle': "Sous-chapitre 8 • Leçon 25/50", 'explanation': "Video games signifie jeux vidéo. On dit play video games pour jouer aux jeux vidéo.", 'example': "They play video games after school. = Ils jouent aux jeux vidéo après l’école.", 'french': "Ils jouent aux jeux vidéo après l’école.", 'question': "Comment dire « jouer aux jeux vidéo » ?", 'options': <String>["play video games", "do video games", "make video games (pour jouer)"], 'answer': 0, 'correction': "On utilise play avec les jeux.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L26", 'level': 'A1', 'title': "Football et basketball", 'subtitle': "Sous-chapitre 8 • Leçon 26/50", 'explanation': "Football signifie soccer en anglais américain ; basketball est le basket-ball. Pour parler du sport pratiqué, on utilise play football ou play basketball.", 'example': "I play football with my friends. = Je joue au football avec mes amis.", 'french': "Je joue au football avec mes amis.", 'question': "Quel verbe utilise-t-on avec football ?", 'options': <String>["play", "do", "make"], 'answer': 0, 'correction': "Play est utilisé avec de nombreux sports d’équipe.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L27", 'level': 'A1', 'title': "Actions sportives de base", 'subtitle': "Sous-chapitre 8 • Leçon 27/50", 'explanation': "Les actions incluent run, jump, kick, throw, catch et swim. Apprends-les avec des images ou des mouvements simples.", 'example': "The player kicks the ball. = Le joueur frappe le ballon du pied.", 'french': "Le joueur frappe le ballon du pied.", 'question': "Kick signifie…", 'options': <String>["Frapper du pied", "Attraper", "Sauter"], 'answer': 0, 'correction': "Kick est l’action de donner un coup de pied.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L28", 'level': 'A1', 'title': "Team et player", 'subtitle': "Sous-chapitre 8 • Leçon 28/50", 'explanation': "Team signifie équipe ; player signifie joueur. Ces mots servent à parler des sports et des jeux.", 'example': "Our team is strong. = Notre équipe est forte.", 'french': "Notre équipe est forte.", 'question': "Player signifie…", 'options': <String>["Joueur", "Entraîneur seulement", "Ballon"], 'answer': 0, 'correction': "Player désigne une personne qui joue.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L29", 'level': 'A1', 'title': "Play football et play basketball", 'subtitle': "Sous-chapitre 8 • Leçon 29/50", 'explanation': "Play + sport est une structure fréquente. Dans une phrase avec he/she/it, on ajoute -s : He plays basketball.", 'example': "She plays basketball. = Elle joue au basket.", 'french': "Elle joue au basket.", 'question': "Complète : He ___ football.", 'options': <String>["play", "plays", "playing"], 'answer': 1, 'correction': "Avec he au présent simple, play devient plays.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L30", 'level': 'A1', 'title': "Go swimming et go running", 'subtitle': "Sous-chapitre 8 • Leçon 30/50", 'explanation': "Pour certaines activités, on utilise go + verbe en -ing : go swimming, go running, go shopping.", 'example': "We go swimming on Sundays. = Nous allons nager le dimanche.", 'french': "Nous allons nager le dimanche.", 'question': "Quelle expression est correcte ?", 'options': <String>["go swim", "go swimming", "go to swimming"], 'answer': 1, 'correction': "L’expression est go + activité en -ing.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L31", 'level': 'A1', 'title': "Do exercise", 'subtitle': "Sous-chapitre 8 • Leçon 31/50", 'explanation': "Do exercise signifie faire de l’exercice. Exercise peut être indénombrable quand on parle d’activité physique en général.", 'example': "I do exercise every morning. = Je fais de l’exercice chaque matin.", 'french': "Je fais de l’exercice chaque matin.", 'question': "Comment dire « faire de l’exercice » ?", 'options': <String>["do exercise", "make exercise", "play exercise"], 'answer': 0, 'correction': "Do exercise est une expression courante.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L32", 'level': 'A1', 'title': "Can pour exprimer une capacité", 'subtitle': "Sous-chapitre 8 • Leçon 32/50", 'explanation': "Can signifie pouvoir ou savoir faire quelque chose. Il est suivi de la base verbale sans to : can swim, can speak.", 'example': "I can swim. = Je sais nager.", 'french': "Je sais nager.", 'question': "Complète : I can ___ English.", 'options': <String>["speak", "speaks", "to speak"], 'answer': 0, 'correction': "Après can, utilise la base verbale sans to.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L33", 'level': 'A1', 'title': "Can’t pour une incapacité", 'subtitle': "Sous-chapitre 8 • Leçon 33/50", 'explanation': "Can’t est la contraction de cannot et signifie ne pas pouvoir ou ne pas savoir faire. Il est suivi de la base verbale.", 'example': "I can’t drive. = Je ne sais pas conduire.", 'french': "Je ne sais pas conduire.", 'question': "Can’t signifie…", 'options': <String>["Pouvoir", "Ne pas pouvoir", "Devoir"], 'answer': 1, 'correction': "Can’t est la négation de can.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L34", 'level': 'A1', 'title': "Question Can you swim?", 'subtitle': "Sous-chapitre 8 • Leçon 34/50", 'explanation': "Pour demander une capacité, place can avant le sujet : Can you swim? Réponds Yes, I can ou No, I can’t.", 'example': "Can you swim? — Yes, I can. = Sais-tu nager ? — Oui.", 'french': "Sais-tu nager ? — Oui.", 'question': "Quelle question demande si quelqu’un sait nager ?", 'options': <String>["Can you swim?", "Do you can swim?", "Are you swim?"], 'answer': 0, 'correction': "Can précède le sujet dans une question.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L35", 'level': 'A1', 'title': "Répondre Yes, I can et No, I can’t", 'subtitle': "Sous-chapitre 8 • Leçon 35/50", 'explanation': "Les réponses courtes reprennent can : Yes, I can ; No, I can’t. N’ajoute pas do à cette structure.", 'example': "Can you cook? — No, I can’t. = Sais-tu cuisiner ? — Non.", 'french': "Sais-tu cuisiner ? — Non.", 'question': "Quelle réponse négative est correcte ?", 'options': <String>["No, I don’t can.", "No, I can’t.", "No, I can’t to."], 'answer': 1, 'correction': "La réponse courte reprend can’t.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L36", 'level': 'A1', 'title': "Parler de ses activités préférées", 'subtitle': "Sous-chapitre 8 • Leçon 36/50", 'explanation': "Utilise I like, I love ou My favorite activity is… pour parler des loisirs. Donne un exemple pour rendre ta réponse plus complète.", 'example': "My favorite activity is playing football. = Mon activité préférée est de jouer au football.", 'french': "Mon activité préférée est de jouer au football.", 'question': "Favorite signifie…", 'options': <String>["Préféré", "Difficile", "Nouveau"], 'answer': 0, 'correction': "Favorite signifie préféré en anglais américain.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L37", 'level': 'A1', 'title': "Proposer Let’s…", 'subtitle': "Sous-chapitre 8 • Leçon 37/50", 'explanation': "Let’s + verbe signifie « faisons… » ou « allons… ». C’est une proposition informelle : Let’s play, Let’s go, Let’s study.", 'example': "Let’s play football. = Jouons au football.", 'french': "Jouons au football.", 'question': "Complète : Let’s ___ English.", 'options': <String>["study", "studies", "studying"], 'answer': 0, 'correction': "Après Let’s, utilise la base verbale.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L38", 'level': 'A1', 'title': "Inviter avec Do you want to…?", 'subtitle': "Sous-chapitre 8 • Leçon 38/50", 'explanation': "Do you want to…? signifie « Veux-tu… ? ». La structure est do + sujet + want to + verbe de base.", 'example': "Do you want to play? = Veux-tu jouer ?", 'french': "Veux-tu jouer ?", 'question': "Quelle question est correcte ?", 'options': <String>["Do you want play?", "Do you want to play?", "Are you want to play?"], 'answer': 1, 'correction': "Want est suivi de to avant le verbe d’action.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L39", 'level': 'A1', 'title': "Inviter avec Would you like to…?", 'subtitle': "Sous-chapitre 8 • Leçon 39/50", 'explanation': "Would you like to…? est une invitation plus polie que Do you want to…? Elle est utile avec des personnes que l’on connaît peu.", 'example': "Would you like to join us? = Voudrais-tu te joindre à nous ?", 'french': "Voudrais-tu te joindre à nous ?", 'question': "Quelle formule est plus polie ?", 'options': <String>["Would you like to…?", "Give me…", "You come now."], 'answer': 0, 'correction': "Would you like est une formule polie.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L40", 'level': 'A1', 'title': "Accepter une invitation", 'subtitle': "Sous-chapitre 8 • Leçon 40/50", 'explanation': "Pour accepter, dis Sure!, Yes, I’d love to ou That sounds great. La réponse dépend du contexte et de ton enthousiasme.", 'example': "Yes, I’d love to! = Oui, avec plaisir !", 'french': "Oui, avec plaisir !", 'question': "Quelle réponse accepte avec enthousiasme ?", 'options': <String>["No, thanks.", "Yes, I’d love to!", "I don’t know your name."], 'answer': 1, 'correction': "I’d love to signifie avec plaisir / j’aimerais beaucoup.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L41", 'level': 'A1', 'title': "Refuser poliment une invitation", 'subtitle': "Sous-chapitre 8 • Leçon 41/50", 'explanation': "Pour refuser, dis Sorry, I can’t ou Thanks for inviting me, but I’m busy. Une courte explication peut adoucir le refus.", 'example': "Sorry, I can’t. I’m busy tonight. = Désolé, je ne peux pas. Je suis occupé ce soir.", 'french': "Désolé, je ne peux pas. Je suis occupé ce soir.", 'question': "Quelle réponse refuse poliment ?", 'options': <String>["No!", "Sorry, I can’t.", "Go away."], 'answer': 1, 'correction': "Sorry adoucit le refus ; can’t indique l’impossibilité.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L42", 'level': 'A1', 'title': "Proposer une autre heure", 'subtitle': "Sous-chapitre 8 • Leçon 42/50", 'explanation': "Si tu n’es pas disponible, propose une alternative : Can we meet tomorrow? ou How about Saturday?", 'example': "I’m busy today. How about tomorrow? = Je suis occupé aujourd’hui. Et demain ?", 'french': "Je suis occupé aujourd’hui. Et demain ?", 'question': "How about tomorrow? signifie…", 'options': <String>["Et demain ?", "Où est demain ?", "Combien demain ?"], 'answer': 0, 'correction': "How about sert à proposer une alternative.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L43", 'level': 'A1', 'title': "Question What do you do for fun?", 'subtitle': "Sous-chapitre 8 • Leçon 43/50", 'explanation': "Cette question signifie « Qu’est-ce que tu fais pour t’amuser ? ». Elle sert à parler des loisirs et activités préférées.", 'example': "What do you do for fun? — I play basketball. = Que fais-tu pour t’amuser ? — Je joue au basket.", 'french': "Que fais-tu pour t’amuser ? — Je joue au basket.", 'question': "Que demande What do you do for fun?", 'options': <String>["Les loisirs", "Le nom de famille", "L’heure"], 'answer': 0, 'correction': "For fun signifie pour le plaisir.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L44", 'level': 'A1', 'title': "Plan simple du week-end", 'subtitle': "Sous-chapitre 8 • Leçon 44/50", 'explanation': "Pour parler du week-end, utilise on Saturday, on Sunday, this weekend et next weekend. Ajoute les activités avec le présent simple ou une proposition Let’s.", 'example': "This weekend, I’m going to play football. = Ce week-end, je vais jouer au football.", 'french': "Ce week-end, je vais jouer au football.", 'question': "This weekend signifie…", 'options': <String>["Ce week-end", "Le week-end dernier", "Chaque jour"], 'answer': 0, 'correction': "This indique la période actuelle.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L45", 'level': 'A1', 'title': "With me et with my friends", 'subtitle': "Sous-chapitre 8 • Leçon 45/50", 'explanation': "With signifie avec. On dit with me, with you, with my family ou with my friends.", 'example': "Come with me. = Viens avec moi.", 'french': "Viens avec moi.", 'question': "With signifie…", 'options': <String>["Avec", "Sans", "Avant"], 'answer': 0, 'correction': "With indique l’accompagnement.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L46", 'level': 'A1', 'title': "Présenter son école", 'subtitle': "Sous-chapitre 8 • Leçon 46/50", 'explanation': "Pour présenter une école, utilise This is my school, It is big, My teachers are kind. Relie les phrases pour faire une description cohérente.", 'example': "This is my school. It is big and friendly. = Voici mon école. Elle est grande et accueillante.", 'french': "Voici mon école. Elle est grande et accueillante.", 'question': "Quelle phrase présente une école ?", 'options': <String>["This is my school.", "I school my.", "Where school?"], 'answer': 0, 'correction': "This is présente le lieu.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L47", 'level': 'A1', 'title': "Décrire son sport préféré", 'subtitle': "Sous-chapitre 8 • Leçon 47/50", 'explanation': "Utilise My favorite sport is… et explique pourquoi avec because. Les noms de sports sont généralement précédés de play quand on parle de les pratiquer.", 'example': "My favorite sport is football because it’s exciting. = Mon sport préféré est le football parce que c’est passionnant.", 'french': "Mon sport préféré est le football parce que c’est passionnant.", 'question': "Because signifie…", 'options': <String>["Mais", "Parce que", "Ensuite"], 'answer': 1, 'correction': "Because introduit une raison.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L48", 'level': 'A1', 'title': "Réagir avec That sounds fun", 'subtitle': "Sous-chapitre 8 • Leçon 48/50", 'explanation': "That sounds fun signifie « Ça a l’air amusant ». C’est une réaction naturelle à une proposition ou à une activité.", 'example': "Let’s go swimming. — That sounds fun! = Allons nager. — Ça a l’air amusant !", 'french': "Allons nager. — Ça a l’air amusant !", 'question': "Que signifie That sounds fun?", 'options': <String>["Ça a l’air amusant", "Je suis fatigué", "C’est trop cher"], 'answer': 0, 'correction': "Sounds fun est une réaction positive à une idée.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L49", 'level': 'A1', 'title': "Rencontrer un nouvel ami", 'subtitle': "Sous-chapitre 8 • Leçon 49/50", 'explanation': "Une première conversation peut contenir une salutation, un prénom, une question sur les loisirs et une invitation simple.", 'example': "Hi, I’m Alex. What do you do for fun? = Salut, je suis Alex. Qu’est-ce que tu fais pour t’amuser ?", 'french': "Salut, je suis Alex. Qu’est-ce que tu fais pour t’amuser ?", 'question': "Quelle question parle des loisirs ?", 'options': <String>["What do you do for fun?", "What time is it?", "Where is the bus?"], 'answer': 0, 'correction': "Cette question demande les activités de loisir.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L50", 'level': 'A1', 'title': "Révision : organiser une rencontre", 'subtitle': "Sous-chapitre 8 • Leçon 50/50", 'explanation': "Réutilise les loisirs, can, les invitations, les réponses polies et la proposition d’un autre moment.", 'example': "Would you like to play basketball on Saturday? — I’d love to! = Veux-tu jouer au basket samedi ? — Avec plaisir !", 'french': "Veux-tu jouer au basket samedi ? — Avec plaisir !", 'question': "Quelle réponse accepte l’invitation ?", 'options': <String>["I’d love to!", "I can’t yesterday.", "Where is it?"], 'answer': 0, 'correction': "I’d love to est une réponse positive et naturelle.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L01", 'level': 'A1', 'title': "Comprendre le présent continu", 'subtitle': "Sous-chapitre 9 • Leçon 1/50", 'explanation': "Le présent continu décrit une action en cours au moment où l’on parle. Forme : sujet + am/is/are + verbe en -ing.", 'example': "I am studying now. = Je suis en train d’étudier.", 'french': "Je suis en train d’étudier.", 'question': "Quel est le point principal de cette leçon ?", 'options': <String>["be + verbe en -ing", "Décrire une habitude uniquement", "Nommer une couleur sans contexte"], 'answer': 0, 'correction': "Relis l’explication et l’exemple : ils illustrent la structure ou l’expression étudiée. Les autres choix ne correspondent pas à l’objectif de cette leçon.", 'unit': 9, 'phase': 0},
